
const fields=['date','no','buyerName','buyerAddress','buyerTaxOffice','buyerTaxNo','buyerPhone','buyerEmail','corpHex','rate','currency','payment','bidder','delivery','notes','status','validityDays'];
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function addItem(data={}){const d=document.createElement('div');d.className='item';d.dataset.productId=data.product_id||'';d.dataset.productCode=data.product_code||'';d.innerHTML=`<div class="product-entry"><div class="product-main"><label>Ürün Tanımı</label><input class="desc" value="${esc(data.desc||'')}" placeholder="Örn: SHINING 3D DS EX PRO C" autocomplete="off"><div class="product-results"></div></div><input class="gtip" type="hidden" value="${esc(data.gtip||'')}"><input class="pbrand" type="hidden" value="${esc(data.brand||'')}"><input class="porigin" type="hidden" value="${esc(data.origin||'')}"><input class="pmodel" type="hidden" value="${esc(data.model||'')}"><div class="product-pricing"><div><label>Adet</label><input class="qty" type="number" min="1" value="${esc(data.qty??1)}"></div><div><label>Birim Fiyat</label><input class="price money-input" type="text" inputmode="decimal" value="${formatTrInput(data.price??0)}"></div><div><label>KDV %</label><input class="vat" type="number" value="${esc(data.vat??20)}"></div><button type="button" class="btn danger" onclick="this.closest('.item').remove();render()">×</button></div><div class="serial-optional"><label>Seri No <span class="muted">(Opsiyonel)</span></label><input class="pserial" value="${esc(data.serial||'')}" placeholder="Cihaza ait seri numarası varsa girin"></div></div>`;document.getElementById('items').appendChild(d);d.querySelectorAll('input').forEach(x=>{if(!x.classList.contains('price'))x.addEventListener('input',()=>{if(x.classList.contains('vat'))x.dataset.userChanged='1';render()})});bindMoneyInput(d.querySelector('.price'));const inp=d.querySelector('.desc');inp.addEventListener('input',()=>{clearTimeout(inp._t);inp._t=setTimeout(()=>searchProductsForItem(d),160)});inp.addEventListener('focus',()=>{if(inp.value.trim())searchProductsForItem(d)});render()}
async function searchProductsForItem(item){if(!sb||!currentUser)return;const q=item.querySelector('.desc').value.trim(),box=item.querySelector('.product-results');if(!q){box.style.display='none';return}const {data,error}=await sb.from('products').select('*').eq('company_id',currentCompanyId).eq('active',true).ilike('name','%'+q+'%').order('name').limit(15);if(error||!data?.length){box.style.display='none';return}box.innerHTML=data.map(p=>`<div class="product-result" data-id="${p.id}"><b>${esc(p.name)}</b>${p.gtip?`<br><span class="muted">GTİP: ${esc(p.gtip)}</span>`:''}</div>`).join('');box.querySelectorAll('.product-result').forEach((el,i)=>el.onclick=()=>applyProductToItem(item,data[i]));box.style.display='block'}
function applyProductToItem(item,p){if(!acceptProductCurrency(p,item))return;item.dataset.productId=p.id||'';item.dataset.productCode=p.product_code||'';item.querySelector('.desc').value=p.name||'';item.querySelector('.gtip').value=p.gtip||'';item.querySelector('.pbrand').value=p.brand||'';item.querySelector('.porigin').value=p.origin||'';item.querySelector('.pmodel').value=p.model||'';item.querySelector('.vat').value=p.vat_rate??20;item.querySelector('.price').value=formatTrInput(p.default_price??0);item.querySelector('.product-results').style.display='none';if(p.currency){const map={EUR:'€',USD:'USD',TRY:'TL'};document.getElementById('currency').value=map[p.currency]||p.currency}render()}
function openCatalog(mode='manage'){const o=document.getElementById('catalogOverlay');o.style.display='block';o.dataset.mode=mode;clearCatalogForm();const form=o.querySelector('.catalog-form-card'),bar=document.getElementById('catalogSelectBar');form.style.display=mode==='select'?'none':'block';bar.style.display=mode==='select'?'flex':'none';o.querySelector('.catalog-head .muted').textContent=mode==='select'?'Teklife eklemek istediğiniz ürünleri seçin.':'Ürünleri burada merkezi olarak ekleyin ve düzenleyin.';return loadCatalog()} function closeCatalog(){document.getElementById('catalogOverlay').style.display='none'}
function catalogProductToItem(p){if(!acceptProductCurrency(p))return false;document.querySelectorAll('.item').forEach(x=>{if(!x.querySelector('.desc').value.trim()&&!parseTrNumber(x.querySelector('.price').value))x.remove()});addItem({product_id:p.id,desc:p.name||'',product_code:p.product_code||'',gtip:p.gtip||'',brand:p.brand||'',origin:p.origin||'',model:p.model||'',serial:'',qty:1,price:p.default_price??0,vat:p.vat_rate??20});if(p.currency){const map={EUR:'€',USD:'USD',TRY:'TL'};document.getElementById('currency').value=map[p.currency]||p.currency}saveDraftDebounced();return true}
function addSelectedCatalogProducts(){const ids=[...document.querySelectorAll('.catalog-pick:checked')].map(x=>Number(x.value));if(!ids.length){alert('Lütfen en az bir ürün seçin.');return}const selected=ids.map(id=>(window._catalog||[]).find(x=>Number(x.id)===id)).filter(Boolean);if(new Set(selected.map(p=>p.currency||currencyDbFromUi(val('currency')))).size>1){alert('Farklı para birimlerindeki ürünleri aynı teklife eklemeyin. Fiyatları önce tek para birimine dönüştürün.');return}if(selected.length&&!acceptProductCurrency(selected[0]))return;ids.forEach(id=>{const p=(window._catalog||[]).find(x=>Number(x.id)===id);if(p)catalogProductToItem(p)});closeCatalog();render()}
function addOneCatalogProduct(id){const p=(window._catalog||[]).find(x=>Number(x.id)===Number(id));if(!p)return;if(catalogProductToItem(p)===false)return;closeCatalog();render()}
function clearCatalogForm(){['catCode','catName','catGtip','catBrand','catOrigin','catModel','catPrice','catDescription'].forEach(id=>document.getElementById(id).value='');document.getElementById('catVat').value='20';document.getElementById('catCurrency').value='EUR';document.getElementById('catStock').value='0';document.getElementById('catLow').value='5';document.getElementById('catGood').value='15';delete document.getElementById('catalogOverlay').dataset.editId}
async function piSaveCatalogProductBase(){if(!['catPrice','catVat','catStock','catLow','catGood'].every(id=>{const n=id==='catPrice'?parseTrNumber(val(id)):Number(val(id));return Number.isFinite(n)&&n>=0})||Number(val('catVat'))>100||Number(val('catGood'))<Number(val('catLow'))){alert('Fiyat, stok ve eşik değerlerini kontrol edin. KDV 0–100 arasında olmalı; yeterli stok sınırı kritik sınırdan küçük olamaz.');return}const name=document.getElementById('catName').value.trim();if(!name){alert('Ürün adını yazın.');return}const payload={company_id:currentCompanyId,is_service_part:document.getElementById('catServicePart').checked,name,product_code:catCode.value.trim(),gtip:catGtip.value.trim(),brand:catBrand.value.trim(),origin:catOrigin.value.trim(),model:catModel.value.trim(),default_price:parseTrNumber(catPrice.value),vat_rate:+catVat.value||0,currency:catCurrency.value,description:catDescription.value.trim(),stock_quantity:Math.max(0,+catStock.value||0),stock_low_threshold:Math.max(0,Number(catLow.value)),stock_good_threshold:Math.max(Number(catLow.value),Number(catGood.value)),active:true,updated_at:new Date().toISOString()};const id=document.getElementById('catalogOverlay').dataset.editId,saveKey=opsKey(),editToken=piEditToken;payload.image_path=await piPrepareSave();if(saveKey!==opsKey()||editToken!==piEditToken)throw Error('Ürün veya çalışma alanı değişti; kaydı yeniden açın.');const {error}=id?await sb.from('products').update(payload).eq('company_id',currentCompanyId).eq('id',id):await sb.from('products').insert(payload);if(error){alert('Ürün kaydedilemedi: '+error.message);return}clearCatalogForm();await loadCatalog();alert('Ürün kataloğa kaydedildi.')}
async function loadCatalog(){const {data,error}=await sb.from('products').select('*').eq('company_id',currentCompanyId).eq('active',true).order('name').limit(250);const box=document.getElementById('catalogList');if(error){box.innerHTML='<div class="muted">'+esc(error.message)+'</div>';return}window._catalog=data||[];const cq=(document.getElementById('catalogQuery')?.value||'').trim().toLocaleLowerCase('tr-TR');const shown=cq?(data||[]).filter(p=>[p.name,p.product_code,p.gtip,p.brand,p.model].some(v=>String(v||'').toLocaleLowerCase('tr-TR').includes(cq))):(data||[]);const selecting=document.getElementById('catalogOverlay').dataset.mode==='select';box.innerHTML=shown.map(p=>{const badge=stockBadge(p);return selecting?`<div class="catalog-row" style="grid-template-columns:38px 1.5fr .8fr .7fr 110px"><input class="catalog-pick" type="checkbox" value="${p.id}" style="width:18px;height:18px"><div><b>${esc(p.name)}</b><br><span class="muted">${p.product_code?'<span class="catalog-code">'+esc(p.product_code)+'</span> • ':''}${p.gtip?'GTİP: '+esc(p.gtip):''} ${p.brand?'• '+esc(p.brand):''}</span></div><div><b>${p.default_price!=null?money(+p.default_price):''}</b> ${esc(p.currency||'')}</div><div>${badge}</div><button type="button" class="btn light" onclick="addOneCatalogProduct(${p.id})">Teklife Ekle</button></div>`:`<div class="catalog-row" style="grid-template-columns:1.5fr .7fr .7fr 100px"><div><b>${esc(p.name)}</b><br><span class="muted">${p.product_code?'<span class="catalog-code">'+esc(p.product_code)+'</span> • ':''}${p.gtip?'GTİP: '+esc(p.gtip):'GTİP girilmemiş'} • ${esc(p.brand||'')}</span></div><div>${p.default_price!=null?money(+p.default_price):''} ${esc(p.currency||'')}</div><div>${badge}</div><button type="button" class="btn light" onclick="editCatalogProduct(${p.id})">Düzenle</button></div>`}).join('')||'<div class="muted">Henüz kayıtlı ürün yok.</div>'}
function editCatalogProduct(id){const p=(window._catalog||[]).find(x=>x.id===id);if(!p)return;document.getElementById('catalogOverlay').dataset.editId=id;catCode.value=p.product_code||'';catName.value=p.name||'';catGtip.value=p.gtip||'';catBrand.value=p.brand||'';catOrigin.value=p.origin||'';catModel.value=p.model||'';catPrice.value=formatTrInput(p.default_price??'');catVat.value=p.vat_rate??20;catCurrency.value=p.currency||'EUR';catDescription.value=p.description||'';catStock.value=p.stock_quantity??0;catLow.value=p.stock_low_threshold??5;catGood.value=p.stock_good_threshold??15;document.querySelector('#catalogOverlay .catalog-form-card').scrollIntoView({behavior:'smooth',block:'start'})}

function stockLevel(p){const q=Number(p.stock_quantity||0),low=Number(p.stock_low_threshold??5),good=Number(p.stock_good_threshold??15);return q<low?'red':q<good?'yellow':'green'}
function stockBadge(p){const q=Number(p.stock_quantity||0),level=stockLevel(p),txt=level==='red'?'Kritik':level==='yellow'?'Az':'Yeterli';return `<span class="stock-badge stock-${level}">${q} Adet • ${txt}</span>`}
async function openStockControl(){
 const movement=document.querySelector('.stock-movement'),type=document.getElementById('moveType');
 if(currentMembership?.role==='service'){
   type.innerHTML='<option value="Servis">Serviste Kullan</option>';
   document.getElementById('moveNote').placeholder='Servis no veya kullanım açıklaması (zorunlu)';
 }else if(!type.querySelector('option[value="Servis"]')){
   type.insertAdjacentHTML('beforeend','<option value="Servis">Serviste Kullan</option>');
 }
 movement.hidden=currentMembership?.role==='viewer';
 document.getElementById('stockOverlay').style.display='block';await loadStockControl()
}
function closeStockControl(){document.getElementById('stockOverlay').style.display='none'}
async function loadStockControl(){const {data,error}=await sb.from('products').select('*').eq('company_id',currentCompanyId).eq('active',true).order('name');if(error){document.getElementById('stockList').innerHTML='<div class="muted">'+esc(error.message)+'</div>';return}window._stockProducts=data||[];const sel=document.getElementById('moveProduct');sel.innerHTML=(data||[]).map(p=>`<option value="${p.id}">${esc(p.name)} (${p.stock_quantity||0})</option>`).join('');renderStockControl()}
function renderStockControl(){const all=window._stockProducts||[],q=(document.getElementById('stockQuery')?.value||'').toLocaleLowerCase('tr-TR'),filter=document.getElementById('stockFilter')?.value||'all';const counts={red:0,yellow:0,green:0};all.forEach(p=>counts[stockLevel(p)]++);stockRedCount.textContent=counts.red;stockYellowCount.textContent=counts.yellow;stockGreenCount.textContent=counts.green;const rows=all.filter(p=>(!q||String(p.name||'').toLocaleLowerCase('tr-TR').includes(q))&&(filter==='all'||(filter==='empty'?Number(p.stock_quantity)===0:stockLevel(p)===filter)));stockList.innerHTML=`<table class="stock-table"><thead><tr><th>Ürün</th><th>Mevcut Stok</th><th>Durum</th><th>Eşikler</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.name)}</b><br><span class="muted">${esc(p.brand||'')}</span></td><td><b>${p.stock_quantity||0} Adet</b></td><td>${stockBadge(p)}</td><td><span class="muted">Kritik &lt; ${p.stock_low_threshold??5} • Yeşil ≥ ${p.stock_good_threshold??15}</span></td><td><button class="btn light" onclick="openCatalogForStock(${p.id})">Düzenle</button></td></tr>`).join('')}</tbody></table>`}
async function openCatalogForStock(id){closeStockControl();await openCatalog('manage');editCatalogProduct(id)}
async function saveStockMovement(){
 if(currentMembership?.role==='service'&&moveType.value!=='Servis'){alert('Teknik servis yalnızca servis stok çıkışı yapabilir.');return}
 if(moveType.value==='Servis'){
  const id=Number(moveProduct.value),quantity=Number(moveQty.value),note=moveNote.value.trim();
  if(!Number.isSafeInteger(id)||!Number.isSafeInteger(quantity)||quantity<1||!note){alert('Ürün, pozitif tam sayı adet ve servis açıklaması gerekli.');return}
  const {error}=await sb.rpc('use_service_stock',{p_company_id:currentCompanyId,p_product_id:id,p_quantity:quantity,p_note:note});
  if(error){alert('Servis stok işlemi yapılamadı: '+error.message);await loadStockControl();return}
  moveQty.value=1;moveNote.value='';await loadStockControl();await checkLowStock();return
 }
 const id=Number(moveProduct.value),type=moveType.value,raw=Number(moveQty.value),p=(window._stockProducts||[]).find(x=>Number(x.id)===id);if(!p||!Number.isFinite(raw)||raw<0||!raw&&type!=='Düzeltme'){alert('Geçerli ürün ve adet seçin.');return}let next=Number(p.stock_quantity||0),delta=raw;if(type==='Giriş'||type==='İade')next+=raw;else if(type==='Satış'||type==='Demo'){next-=raw;delta=-raw}else if(type==='Düzeltme'){next=raw;delta=raw-Number(p.stock_quantity||0)}if(next<0){alert('Stok eksiye düşemez. Mevcut stok: '+p.stock_quantity);return}const now=new Date().toISOString();const {data:changed,error:e1}=await sb.from('products').update({stock_quantity:next,updated_at:now}).eq('company_id',currentCompanyId).eq('id',id).eq('stock_quantity',p.stock_quantity).select('id').maybeSingle();if(!e1&&!changed){alert('Stok başka bir işlemle değişti. Liste yenileniyor; tekrar kontrol edin.');await loadStockControl();return}if(e1){alert('Stok güncellenemedi: '+e1.message);return}const {error:e2}=await sb.from('stock_movements').insert({company_id:currentCompanyId,product_id:id,movement_type:type,quantity:delta,note:moveNote.value.trim()||null});if(e2){alert('Stok güncellendi ancak hareket kaydı yazılamadı: '+e2.message)}moveQty.value=1;moveNote.value='';await loadStockControl();await checkLowStock()}
async function checkLowStock(){if(!currentUser)return;const [{data:notes,error},{data:reads}]=await Promise.all([sb.from('stock_notifications').select('product_id,severity,active,cycle,stock_quantity,last_checked_at,products(name)').eq('active',true).order('severity'),sb.from('stock_notification_reads').select('product_id,cycle').eq('user_id',currentUser.id)]);if(error)return;const readSet=new Set((reads||[]).map(r=>`${r.product_id}:${r.cycle}`)),alerts=(notes||[]).map(n=>({...n,name:n.products?.name||'Ürün',read:readSet.has(`${n.product_id}:${n.cycle}`)}));window._stockNotifications=alerts;const unread=alerts.filter(x=>!x.read),badge=document.getElementById('notifyCount'),list=document.getElementById('notifyList');if(badge){badge.textContent=unread.length>99?'99+':unread.length;badge.style.display=unread.length?'block':'none'}if(list){list.className='';list.innerHTML=alerts.length?alerts.map(p=>{const label=p.severity==='red'?'Kritik stok':'Stok azalıyor';return `<div class="notify-item ${p.read?'read':''}" onclick="openStockFromNotification(${p.product_id},${p.cycle})"><span class="notify-dot ${p.severity}"></span><div><div class="notify-title">${esc(p.name)} — ${p.stock_quantity} adet ${p.read?'✓':''}</div><div class="notify-sub">${label} • ${p.read?'Okundu':'Yeni bildirim'}</div></div></div>`}).join(''):'<div class="notify-empty">✓ Şu anda stok bildirimi yok.</div>';const mb=document.getElementById('mobileNotifyCount'),ml=document.getElementById('mobileNotifyList');if(mb){mb.textContent=unread.length>99?'99+':unread.length;mb.style.display=unread.length?'block':'none'}if(ml){ml.innerHTML=alerts.length?alerts.map(p=>{const label=p.severity==='red'?'Kritik stok':'Stok azalıyor';return `<div class="notify-item ${p.read?'read':''}" onclick="openStockFromNotification(${p.product_id},${p.cycle});closeMobileNotifications()"><span class="notify-dot ${p.severity}"></span><div><div class="notify-title">${esc(p.name)} — ${p.stock_quantity} adet ${p.read?'✓':''}</div><div class="notify-sub">${label} • ${p.read?'Okundu':'Yeni bildirim'}</div></div></div>`}).join(''):'<div class="notify-empty">✓ Şu anda stok bildirimi yok.</div>'}}}
function toggleNotifications(e){if(e)e.stopPropagation();document.getElementById('notifyPanel')?.classList.toggle('open')}
function toggleMobileNotifications(e){if(e)e.stopPropagation();const shell=document.getElementById('mobileNotifyShell');if(!shell)return;shell.classList.toggle('open');if(shell.classList.contains('open')){window._notifyReturnFocus=e?.currentTarget||document.activeElement;shell.querySelector('.mobile-notify-head button')?.focus();checkLowStock().catch(console.error)}}
function closeMobileNotifications(){document.getElementById('mobileNotifyShell')?.classList.remove('open');window._notifyReturnFocus?.focus?.()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('mobileNotifyShell')?.classList.contains('open'))closeMobileNotifications()});
function closeMobileNavThen(fn){
  const t=document.getElementById('mobileNavToggle');
  if(t)t.checked=false;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{if(typeof fn==='function')fn()}));
}
function openMobileCustomers(){document.getElementById('mobileNavToggle').checked=false;openCustomers()}
async function markNotificationRead(id,cycle){if(!currentUser)return;await sb.from('stock_notification_reads').upsert({user_id:currentUser.id,product_id:Number(id),cycle:Number(cycle),read_at:new Date().toISOString()},{onConflict:'user_id,product_id,cycle'});await checkLowStock()}
async function markAllNotificationsRead(e){if(e)e.stopPropagation();if(!currentUser)return;const unread=(window._stockNotifications||[]).filter(x=>!x.read);if(unread.length)await sb.from('stock_notification_reads').upsert(unread.map(x=>({user_id:currentUser.id,product_id:x.product_id,cycle:x.cycle,read_at:new Date().toISOString()})),{onConflict:'user_id,product_id,cycle'});await checkLowStock()}
async function openStockFromNotification(id,cycle){await markNotificationRead(id,cycle);document.getElementById('notifyPanel')?.classList.remove('open');await openStockControl();stockQuery.value='';const n=(window._stockNotifications||[]).find(p=>Number(p.product_id)===Number(id));stockFilter.value=n?.severity==='red'?'red':'yellow';renderStockControl();setTimeout(()=>{const sel=document.getElementById('moveProduct');if(sel)sel.value=String(id)},0)}
document.addEventListener('click',e=>{const w=document.getElementById('notifyWrap');if(w&&!w.contains(e.target))document.getElementById('notifyPanel')?.classList.remove('open')});
function val(id){return document.getElementById(id).value}
function trTitleCase(v){return String(v||'').trim().toLocaleLowerCase('tr-TR').replace(/(^|[\s\-\/().,'’]+)([a-zçğıöşü])/giu,(m,sep,ch)=>sep+ch.toLocaleUpperCase('tr-TR'));}
function trUpper(v){return String(v||'').trim().toLocaleUpperCase('tr-TR');}
function normalizeCustomerFields(){const bidderEl=document.getElementById('bidder');if(bidderEl)bidderEl.value=trTitleCase(bidderEl.value);['buyerName','buyerAddress'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=trTitleCase(e.value)});const tax=document.getElementById('buyerTaxOffice');if(tax)tax.value=trUpper(tax.value);}
function parseTrNumber(v){let s=String(v??'').trim().replace(/\s/g,'').replace(/[^0-9,.-]/g,'');if(!s)return 0;if(s.includes(',')){s=s.replace(/\./g,'').replace(',','.')}else if(s.includes('.')){const parts=s.split('.');const looksGrouped=parts.length>1&&parts.slice(1).every(x=>/^\d{3}$/.test(x));if(looksGrouped)s=parts.join('');}return Number(s)||0}
function formatTrInput(v){if(v===null||v===undefined||v==='')return '';if(typeof v==='number')return new Intl.NumberFormat('tr-TR',{maximumFractionDigits:4}).format(v);let raw=String(v).replace(/[^0-9,.-]/g,'').replace(/-/g,'');if(raw.includes(',')){let [a,b='']=raw.split(',');a=a.replace(/\./g,'');a=(a||'0').replace(/^0+(?=\d)/,'');return a.replace(/\B(?=(\d{3})+(?!\d))/g,'.')+','+b.slice(0,4)}let a=raw.replace(/\./g,'').replace(/^0+(?=\d)/,'');return (a||'0').replace(/\B(?=(\d{3})+(?!\d))/g,'.')}
function bindMoneyInput(el){if(!el)return;el.addEventListener('input',()=>{const pos=el.selectionStart;const before=el.value.length;el.value=formatTrInput(el.value);const diff=el.value.length-before;try{el.setSelectionRange(Math.max(0,pos+diff),Math.max(0,pos+diff))}catch(e){};render()});el.addEventListener('blur',()=>{el.value=formatTrInput(el.value)})}
function money(n){return new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)}
function getBanks(){return [...document.querySelectorAll('.bank-editor')].map(x=>({id:x.dataset.bankId||undefined,name:x.querySelector('.bname').value,branch:x.querySelector('.bbranch').value,holder:x.querySelector('.bholder').value,currency:x.querySelector('.bcurrency').value,iban:x.querySelector('.biban').value,swift:x.querySelector('.bswift').value})).filter(b=>Object.values(b).some(Boolean))}
function addBank(data={}){const d=document.createElement('div');d.className='bank-editor';d.dataset.bankId=data.id||'';d.innerHTML=`<div class="bank-editor-head"><b>Banka Hesabı</b><button type="button" class="btn danger" style="padding:6px 9px" onclick="this.closest('.bank-editor').remove();render()">×</button></div><div class="grid"><input class="bname full" placeholder="Banka adı" value="${esc(data.name||'')}"><input class="bbranch" placeholder="Şube" value="${esc(data.branch||'')}"><input class="bholder" placeholder="Hesap sahibi" value="${esc(data.holder||'')}"><select class="bcurrency"><option ${data.currency==='TRY'?'selected':''}>TRY</option><option ${data.currency==='EUR'?'selected':''}>EUR</option><option ${data.currency==='USD'?'selected':''}>USD</option></select><input class="bswift" placeholder="SWIFT / BIC" value="${esc(data.swift||'')}"><input class="biban full" placeholder="IBAN" value="${esc(data.iban||'')}"></div>`;document.getElementById('bankEditors').appendChild(d);d.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',render));render()}
function setCorpColor(c){if(!/^#[0-9a-f]{6}$/i.test(c))return;document.documentElement.style.setProperty('--corp',c);document.getElementById('corpColor').value=c;document.getElementById('corpHex').value=c;render()}
function setPayment(text){document.getElementById('payment').value=text;render();saveDraftDebounced()}
