async function saveBanksCloud(silent=false){if(!currentUser||!currentCompanyId)return false;try{const banks=getBanks(),{data:existing,error:readError}=await sb.from('bank_accounts').select('id').eq('company_id',currentCompanyId);if(readError)throw readError;const retained=new Set();for(const [i,b] of banks.entries()){const row={company_id:currentCompanyId,bank_name:b.name,branch:b.branch,account_holder:b.holder,currency:b.currency,iban:b.iban,swift:b.swift,sort_order:i+1,active:true};const query=b.id?sb.from('bank_accounts').update(row).eq('company_id',currentCompanyId).eq('id',b.id):sb.from('bank_accounts').insert(row);const {data,error}=await query.select('id').single();if(error)throw error;retained.add(String(data.id));const editor=[...document.querySelectorAll('.bank-editor')].filter(x=>Object.values({name:x.querySelector('.bname').value,iban:x.querySelector('.biban').value,holder:x.querySelector('.bholder').value,branch:x.querySelector('.bbranch').value,currency:x.querySelector('.bcurrency').value,swift:x.querySelector('.bswift').value}).some(Boolean))[i];if(editor)editor.dataset.bankId=data.id;}const removed=(existing||[]).filter(x=>!retained.has(String(x.id))).map(x=>x.id);if(removed.length){const {error}=await sb.from('bank_accounts').delete().eq('company_id',currentCompanyId).in('id',removed);if(error)throw error;}if(!silent)alert('Banka bilgileri kaydedildi.');return true}catch(e){alert('Banka bilgilerinin tamamı kaydedilemedi. Mevcut kayıtlar korunmuştur. '+e.message);return false}}
async function createWorkspace(){
  const companyName=document.getElementById('onboardCompany').value.trim();
  const person=document.getElementById('onboardPerson').value.trim();
  const phone=document.getElementById('onboardPhone').value.trim();
  const msg=document.getElementById('onboardMsg');
  if(!currentUser){msg.textContent='Oturum bulunamadı. Lütfen tekrar giriş yapın.';return}
  if(!companyName){msg.textContent='Firma / Marka Adı alanını doldurun.';document.getElementById('onboardCompany').focus();return}
  msg.textContent='Çalışma alanınız oluşturuluyor…';
  const {data,error}=await sb.rpc('create_company_for_current_user',{p_name:companyName});
  if(error){msg.textContent='Firma oluşturulamadı: '+error.message;return}
  const companyId=data;
  currentCompanyId=companyId;
  const settingsPatch={company_display_name:companyName,legal_name:companyName,phone:phone||null,email:currentUser.email||null,updated_at:new Date().toISOString()};
  const {error:settingsError}=await sb.from('company_settings').update(settingsPatch).eq('company_id',companyId);
  if(settingsError)console.warn('Firma profil bilgileri tamamlanamadı',settingsError);
  if(person){try{await sb.auth.updateUser({data:{full_name:person}})}catch(e){console.warn(e)}}
  msg.textContent='Firma oluşturuldu. Çalışma alanınız açılıyor…';
  window._settingsLoaded=false;window._banksLoaded=false;window._stockChecked=false;
  await resolveWorkspace();
  await bootWorkspace();
}
