function editCustomerManager(id){
  const c=customerManagerData.find(x=>Number(x.id)===Number(id)); if(!c)return;
  document.getElementById('customerEditId').value=c.id;document.getElementById('cmCity').value=c.city||'';
  document.getElementById('cmName').value=c.name||'';document.getElementById('cmTaxOffice').value=c.tax_office||'';
  document.getElementById('cmTaxNo').value=c.tax_number||'';document.getElementById('cmPhone').value=c.phone||'';
  document.getElementById('cmEmail').value=c.email||'';document.getElementById('cmAddress').value=c.address||'';
  document.getElementById('customerForm').classList.add('open');document.getElementById('customerForm').scrollIntoView({behavior:'smooth',block:'start'});
}
function cancelCustomerEdit(){document.getElementById('customerForm')?.classList.remove('open')}
async function saveCustomerManager(){
  const name=document.getElementById('cmName').value.trim(); if(!name){alert('Firma adı zorunludur.');return}
  const id=document.getElementById('customerEditId').value;
  const payload={company_id:currentCompanyId,name,city:val('cmCity'),address:document.getElementById('cmAddress').value.trim(),tax_office:document.getElementById('cmTaxOffice').value.trim(),tax_number:document.getElementById('cmTaxNo').value.trim(),phone:document.getElementById('cmPhone').value.trim(),email:document.getElementById('cmEmail').value.trim(),updated_at:new Date().toISOString()};
  const res=id?await sb.from('customers').update(payload).eq('company_id',currentCompanyId).eq('id',id):await sb.from('customers').insert(payload);
  if(res.error){alert('Müşteri kaydedilemedi: '+res.error.message);return}
  document.getElementById('customerForm').classList.remove('open'); await openCustomers();
}
async function deleteCustomerManager(id){
  const c=customerManagerData.find(x=>Number(x.id)===Number(id)); if(!c)return;
  if(!confirm('“'+(c.name||'Bu müşteri')+'” kaydı silinsin mi?'))return;
  const {error}=await sb.from('customers').delete().eq('company_id',currentCompanyId).eq('id',id);
  if(error){alert('Müşteri silinemedi: '+error.message);return}
  customerManagerData=customerManagerData.filter(x=>Number(x.id)!==Number(id));renderCustomerManager();
}
