async function loadArchive(){if(!sb||!currentUser)return;const q=(document.getElementById('archiveQuery')?.value||'').trim();const limit=+(document.getElementById('archiveLimit')?.value||25);const {data,error}=await sb.from('proformas').select('id,document_scope,proforma_number,proforma_date,customer_name,currency,grand_total,status,status_changed_at,items,created_at,bidder,payment_terms,approval_state,approval_revision,approved_at,approval_requested_at,approval_note').eq('company_id',currentCompanyId).order('created_at',{ascending:false}).limit(limit);let all=data||[];const norm=x=>({...x,status:approvalStatus(x)});all=all.map(norm);document.getElementById('countWait').textContent=all.filter(x=>x.status==='Onaya Gönderildi').length;document.getElementById('countOk').textContent=all.filter(x=>x.status==='Onaylandı').length;document.getElementById('countNo').textContent=all.filter(x=>['Onaylanmadı','Revizyon İstendi'].includes(x.status)).length;['statWait','statOk','statNo'].forEach(id=>document.getElementById(id)?.classList.remove('active'));if(archiveStatusFilter==='Onaya Gönderildi')document.getElementById('statWait')?.classList.add('active');if(archiveStatusFilter==='Onaylandı')document.getElementById('statOk')?.classList.add('active');if(archiveStatusFilter==='Onaylanmadı')document.getElementById('statNo')?.classList.add('active');let rows=archiveStatusFilter?all.filter(x=>x.status===archiveStatusFilter||(archiveStatusFilter==='Onaylanmadı'&&x.status==='Revizyon İstendi')):all;if(q){const z=q.toLocaleLowerCase('tr-TR');rows=rows.filter(x=>(x.proforma_number||'').toLocaleLowerCase('tr-TR').includes(z)||(x.customer_name||'').toLocaleLowerCase('tr-TR').includes(z)||(x.bidder||'').toLocaleLowerCase('tr-TR').includes(z)||(x.items||[]).some(i=>(i.description||'').toLocaleLowerCase('tr-TR').includes(z)));}const box=document.getElementById('archiveList');if(error){box.innerHTML='<p class="muted">Arşiv yüklenemedi: '+esc(error.message)+'</p>';return}window._archiveVisibleRows=rows;box.innerHTML=`<table class="archive-table"><thead><tr><th>Proforma No</th><th>Tarih</th><th>Müşteri</th><th>Teklifi Veren</th><th>Teklif Edilen Ürün</th><th>Durum</th><th>Toplam</th><th></th></tr></thead><tbody>${rows.map(x=>{const c=statusClass(x.status),days=waitingDays(x);const dateText=x.status!=='Onaya Gönderildi'&&x.status_changed_at?`<div class="muted" style="font-size:10px;margin-top:4px">${new Date(x.status_changed_at).toLocaleDateString('tr-TR')}</div>`:(x.status==='Onaya Gönderildi'?`<div class="waiting-age">${days} gündür bekliyor</div>`:'');return `<tr class="archive-row-${c}"><td><b>${esc(x.proforma_number)}</b></td><td>${esc(x.proforma_date||'')}</td><td>${esc(x.customer_name||'')}</td><td><span class="owner-chip">${esc(x.bidder||'-')}</span></td><td style="max-width:240px;font-size:11px">${esc((x.items||[]).map(i=>i.description||i.desc||'').filter(Boolean).join(', ')||'-')}</td><td><span class="status-badge status-${c}">${esc(x.status)}</span>${dateText}${approvalActions(x)}</td><td>${money(+x.grand_total||0)} ${esc(x.currency||'')}</td><td><div class="actions" style="margin:0;flex-wrap:nowrap"><button class="btn light" onclick="openSavedProformaNewTab(${x.id})">Görüntüle / PDF</button><button class="btn light" onclick="uiCopyArchive(${x.id})">Kopyala</button><button class="btn danger" data-number="${esc(x.proforma_number||'')}" onclick="deleteArchivedProforma(${x.id}, this.dataset.number)">Sil</button></div></td></tr>`}).join('')||'<tr><td colspan="8">Kayıtlı proforma bulunamadı.</td></tr>'}</tbody></table>`}
