function closeAllAppLayers(){
  const ids=['archiveOverlay','customerOverlay','settingsOverlay','catalogOverlay','stockOverlay','crmOverlay','calendarOverlay','serviceOverlay','teamOverlay'];
  ids.forEach(id=>{
    const el=document.getElementById(id);
    if(el){el.classList.remove('open');el.style.display='';}
  });
  document.body.style.overflow='';
}
function desktopNavigate(action){
  closeAllAppLayers();
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    if(action==='home'){window.scrollTo({top:0,behavior:'smooth'});return;}
    if(action==='new'){window.scrollTo({top:0,behavior:'smooth'});setTimeout(()=>document.getElementById('buyerName')?.focus(),280);return;}
    if(action==='archive' && typeof openArchive==='function')openArchive();
    if(action==='customers' && typeof openCustomers==='function')openCustomers();
    if(action==='catalog' && typeof openCatalog==='function')openCatalog('manage');
    if(action==='stock' && typeof openStockControl==='function')openStockControl();
    if(action==='settings' && typeof openSettings==='function')openSettings();
  }));
}


function closeAllProeraViews(){
  document.getElementById('dashboardOverlay')?.classList.remove('open');
  ['archiveOverlay','customerOverlay','settingsOverlay','catalogOverlay','stockOverlay','crmOverlay','calendarOverlay','serviceOverlay','teamOverlay'].forEach(id=>{
    const el=document.getElementById(id); if(!el)return;
    el.classList.remove('open'); el.style.display='';
  });
  document.body.style.overflow='';
}
async function appNavigate(action){
  if(!hasAppAction(action)){alert('Bu bölüme erişim yetkiniz yok.');return}
  closeAllProeraViews();
  if(action==='home'){document.getElementById('dashboardOverlay').classList.add('open');return loadDashboard()}
  if(action==='new')return resetForm();
  if(action==='archive')return openArchive();
  if(action==='customers')return openCustomers();
  if(action==='catalog')return openCatalog('manage');
  if(action==='stock')return openStockControl();
  if(action==='team')return openTeam();
  if(action==='settings'){await openSettings();loadProeraPrefs();return}
  if(action==='crm')return openCrm();
  if(action==='calendar')return openCalendar();
  if(action==='service')return openServices();
}
function mobileNavigate(action){if(!hasAppAction(action))return;const t=document.getElementById('mobileNavToggle');if(t)t.checked=false;setTimeout(()=>appNavigate(action),80)}
function openMobileNavFromLayer(){closeAllProeraViews();const t=document.getElementById('mobileNavToggle');if(t)t.checked=true}
