let calendarCursor=new Date(),calendarEvents=[];
function isoLocal(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
async function openCalendar(){closeAllProeraViews();document.getElementById('calendarOverlay')?.classList.add('open');calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),1);await loadCalendar()}
function calendarDate(value){return String(value||'').slice(0,10)}
let calendarLoadVersion=0;
async function loadCalendar(){
 const version=++calendarLoadVersion,first=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),1),start=new Date(first);
 start.setDate(1-((first.getDay()+6)%7));const end=new Date(start);end.setDate(start.getDate()+41);
 const state=document.getElementById('calendarLoadState');state.textContent='Etkinlikler yükleniyor…';renderCalendar();
 try{
  const {data,error}=await sb.from('calendar_events').select('*').eq('company_id',currentCompanyId).gte('event_date',isoLocal(start)).lte('event_date',isoLocal(end)).order('event_date').order('start_time');
  if(version!==calendarLoadVersion)return false;
  if(error)throw error;
  calendarEvents=data||[];renderCalendar();state.textContent=calendarEvents.length?calendarEvents.length+' etkinlik':'Bu tarih aralığında kayıtlı etkinlik yok. Gün kutusuna tıklayarak ekleyebilirsiniz.';return true;
 }catch(e){if(version===calendarLoadVersion)state.textContent='Etkinlikler yüklenemedi: '+e.message;return false}
}
function renderCalendar(){
 document.getElementById('calendarMonthLabel').textContent=calendarCursor.toLocaleDateString('tr-TR',{month:'long',year:'numeric'});
 const grid=document.getElementById('calendarGrid');const names=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];let out=names.map(n=>`<div class="cal-dow">${n}</div>`).join('');
 const first=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),1),start=new Date(first);start.setDate(1-((first.getDay()+6)%7));const today=isoLocal(new Date());
 for(let i=0;i<42;i++){
  const d=new Date(start);d.setDate(start.getDate()+i);const iso=isoLocal(d),events=calendarEvents.filter(x=>calendarDate(x.event_date)===iso).sort((a,b)=>String(a.start_time||'').localeCompare(String(b.start_time||'')));
  out+=`<div class="cal-day ${d.getMonth()!==calendarCursor.getMonth()?'muted':''} ${iso===today?'today':''}" data-date="${iso}"><button type="button" class="cal-num" data-add-date="${iso}" aria-label="${iso} tarihine etkinlik ekle">${d.getDate()}<span aria-hidden="true">+</span></button><div class="cal-events">${events.map(x=>{
   const tone=x.event_type==='Kurulum'?'install':x.event_type==='Servis'?'service':x.event_type==='Toplantı'?'meeting':'';
   const time=x.start_time?String(x.start_time).slice(0,5)+(x.end_time?' – '+String(x.end_time).slice(0,5):''):'Tüm gün';
   return `<button type="button" class="cal-event ${tone}" data-event-id="${esc(x.id)}" aria-label="${esc(x.title)}, ${esc(time)}; düzenle"><span class="cal-event-time">${esc(time)}</span><strong class="cal-event-title">${esc(x.title||'Etkinlik')}</strong>${x.personnel?`<span class="cal-event-person">${esc(x.personnel)}</span>`:''}${x.location?`<span class="cal-event-location">${esc(x.location)}</span>`:''}</button>`
  }).join('')}</div></div>`;
 }
 grid.innerHTML=out;
 grid.querySelectorAll('[data-event-id]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();editCalendarEvent(button.dataset.eventId)}));
 grid.querySelectorAll('[data-add-date]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();newCalendarEvent(button.dataset.addDate)}));
 grid.querySelectorAll('.cal-day').forEach(day=>day.addEventListener('click',e=>{if(!e.target.closest('button'))newCalendarEvent(day.dataset.date)}));
}
function changeCalendarMonth(n){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+n,1);loadCalendar()}
function calendarToday(){calendarCursor=new Date();loadCalendar()}
function newCalendarEvent(date){document.getElementById('calSaveState').textContent='';['calId','calTitle','calStart','calEnd','calPersonnel','calLocation','calNotes'].forEach(id=>document.getElementById(id).value='');document.getElementById('calType').value='Kurulum';document.getElementById('calDate').value=date||isoLocal(new Date());document.getElementById('calDelete').style.display='none';document.getElementById('calendarModal').classList.add('open')}
function editCalendarEvent(id){const x=calendarEvents.find(v=>String(v.id)===String(id));if(!x)return;document.getElementById('calId').value=x.id;document.getElementById('calTitle').value=x.title||'';document.getElementById('calType').value=x.event_type||'Kurulum';document.getElementById('calDate').value=calendarDate(x.event_date);document.getElementById('calStart').value=String(x.start_time||'').slice(0,5);document.getElementById('calEnd').value=String(x.end_time||'').slice(0,5);document.getElementById('calPersonnel').value=x.personnel||'';document.getElementById('calLocation').value=x.location||'';document.getElementById('calNotes').value=x.notes||'';document.getElementById('calDelete').style.display='inline-flex';document.getElementById('calendarModal').classList.add('open')}
function closeCalendarModal(){document.getElementById('calendarModal').classList.remove('open')}
async function saveCalendarEvent(){
 if(window._calendarSaving)return;
 const id=val('calId'),title=val('calTitle').trim(),date=val('calDate');
 if(!title){alert('Başlık yazın.');return}if(!date){alert('Tarih seçin.');return}
 if(val('calStart')&&val('calEnd')&&val('calEnd')<=val('calStart')){alert('Bitiş saati başlangıçtan sonra olmalı.');return}
 if(!sb||!currentCompanyId){alert('Etkinliği kaydetmek için çalışma alanınıza giriş yapın.');return}
 const state=document.getElementById('calSaveState'),button=document.getElementById('calSaveButton');window._calendarSaving=true;button.disabled=true;state.textContent='Kaydediliyor…';
 try{
  const payload={organization_plan:orgGetPlan(),company_id:currentCompanyId,city:val('calCity'),assigned_user_id:val('calAssignee')||null,travel_required:document.getElementById('calTravel').checked,title,event_type:val('calType'),event_date:date,start_time:val('calStart')||null,end_time:val('calEnd')||null,personnel:val('calPersonnel').trim(),location:val('calLocation').trim(),notes:val('calNotes').trim(),reminder_minutes:Number(val('calReminder')||0),completed_at:val('calCompleted')==='done'?(calendarEvents.find(x=>String(x.id)===String(id))?.completed_at||new Date().toISOString()):null,updated_at:new Date().toISOString()};
  const query=id?sb.from('calendar_events').update(payload).eq('company_id',currentCompanyId).eq('id',id):sb.from('calendar_events').insert(payload);
  const {data,error}=await query.select();if(error)throw error;
  const saved=Array.isArray(data)?data[0]:data;if(!saved?.id)throw Error('Kaydedilen etkinlik doğrulanamadı. Hesabınızın kayıt ve okuma yetkilerini kontrol edin.');
  ++calendarLoadVersion;calendarEvents=calendarEvents.filter(x=>String(x.id)!==String(saved.id));calendarEvents.push(saved);
  const [year,month,day]=calendarDate(saved.event_date).split('-').map(Number);calendarCursor=new Date(year,month-1,day);
  renderCalendar();closeCalendarModal();document.getElementById('calendarLoadState').textContent='Etkinlik kaydedildi.';
  const loaded=await loadCalendar();if(loaded)document.getElementById('calendarLoadState').textContent='Etkinlik kaydedildi. '+calendarEvents.length+' etkinlik gösteriliyor.';
  document.querySelector(`[data-date="${date}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'});
  loadDashboardOperations().catch(console.error);
 }catch(e){state.textContent='Kaydedilemedi: '+e.message;alert('Plan kaydedilemedi: '+e.message)}finally{window._calendarSaving=false;button.disabled=false}
}
async function deleteCalendarEvent(){const id=document.getElementById('calId').value;if(!id||!confirm('Bu plan silinsin mi?'))return;const r=await sb.from('calendar_events').delete().eq('company_id',currentCompanyId).eq('id',id).eq('company_id',currentCompanyId);if(r.error){alert(r.error.message);return}closeCalendarModal();await loadCalendar()}


async function loadDashboardOperations(){
 if(!sb||!currentUser||!currentCompanyId)return;
 const today=isoLocal(new Date()),d7=new Date();d7.setDate(d7.getDate()+7);const until=isoLocal(d7);
 const [ce,ci,pf]=await Promise.all([
  sb.from('calendar_events').select('*').eq('company_id',currentCompanyId).gte('event_date',today).lte('event_date',until).order('event_date').order('start_time'),
  sb.from('customer_interactions').select('*').eq('company_id',currentCompanyId).order('interaction_date',{ascending:false}).limit(12),
  sb.from('proformas').select('id,proforma_number,customer_name,status,grand_total,currency,proforma_date').eq('company_id',currentCompanyId).order('created_at',{ascending:false}).limit(20)
 ]);
 const events=ce.data||[], interactions=ci.data||[], proformas=pf.data||[];
 const row=x=>`<div class="schedule-row"><span class="schedule-time">${x.start_time?esc(String(x.start_time).slice(0,5)):'Tüm gün'}</span><span><b>${esc(x.title)}</b><br><small>${esc(x.event_type||'Plan')}</small></span><span class="schedule-person">👤 ${esc(x.personnel||'Personel belirtilmedi')}</span><span>📍 ${esc(x.location||'Yer belirtilmedi')}</span></div>`;
 const todayBox=document.getElementById('dashTodaySchedule');if(todayBox)todayBox.innerHTML=events.filter(x=>x.event_date===today).map(row).join('')||'<div class="muted">Bugün için plan bulunmuyor.</div>';
 const up=document.getElementById('dashUpcomingSchedule');if(up)up.innerHTML=events.filter(x=>x.event_date>today).slice(0,7).map(x=>`<div class="schedule-row"><span class="schedule-time">${new Date(x.event_date+'T12:00:00').toLocaleDateString('tr-TR',{day:'2-digit',month:'short'})}</span><span><b>${esc(x.title)}</b></span><span class="schedule-person">👤 ${esc(x.personnel||'-')}</span><span>📍 ${esc(x.location||'-')}</span></div>`).join('')||'<div class="muted">Önümüzdeki 7 gün için plan yok.</div>';
 const flow=document.getElementById('dashSalesFlow');if(flow)flow.innerHTML=interactions.slice(0,8).map(x=>{const[t,l]=crmTone(x.status),products=((x.product_names&&x.product_names.length)?x.product_names.join(', '):x.product_name)||'Ürün belirtilmedi';const pf=proformas.find(p=>(p.customer_name||'').toLocaleLowerCase('tr-TR')===(x.company_name||x.contact_name||'').toLocaleLowerCase('tr-TR'));return `<div class="sales-flow-row"><span><b>${esc(x.company_name||x.contact_name||'-')}</b><br><small>👤 ${esc(x.sales_rep||'-')}</small></span><span>${esc(products)}</span><span class="status-pill tone-${t}">${l}</span><span>${pf?`<b>${esc(pf.proforma_number||'Proforma')}</b><br><small>${money(+pf.grand_total||0)} ${esc(pf.currency||'')}</small>`:'<small>Henüz proforma yok</small>'}</span></div>`}).join('')||'<div class="muted">Henüz satış görüşmesi yok.</div>';
}


