function acceptProductCurrency(p,except=null){const target=currencyUiFromDb(p.currency||currencyDbFromUi(val('currency')));const occupied=[...document.querySelectorAll('.item')].some(x=>x!==except&&x.querySelector('.desc').value.trim());if(occupied&&target!==val('currency')){alert('Bu ürünün para birimi tekliften farklı. Ayrı teklif oluşturun veya fiyatı dönüştürerek manuel girin.');return false}if(target!==val('currency')){document.getElementById('currency').value=target;fetchRate()}return true}
function setAuthBackground(signedIn){document.body.classList.toggle('auth-required',!signedIn);for(const el of document.body.children){if(!['SCRIPT','STYLE'].includes(el.tagName)&&el.id!=='authGate')el.inert=!signedIn}if(signedIn)document.getElementById('mobileDrawer').inert=!document.getElementById('mobileNavToggle').checked}
function draftKey(){return currentUser&&currentCompanyId?'proera_draft_v2:'+currentUser.id+':'+currentCompanyId:null}
function collectDraft(){const d={};fields.forEach(id=>d[id]=val(id));d.items=[...document.querySelectorAll('.item')].map(x=>({product_id:x.dataset.productId||null,currency_conversion:readItemConversion(x),product_code:x.dataset.productCode||'',desc:x.querySelector('.desc').value,gtip:x.querySelector('.gtip').value,brand:x.querySelector('.pbrand').value,origin:x.querySelector('.porigin').value,model:x.querySelector('.pmodel').value,serial:x.querySelector('.pserial').value,qty:Number(x.querySelector('.qty').value),price:parseTrNumber(x.querySelector('.price').value),vat:Number(x.querySelector('.vat').value)}));return {...d,vatMode:document.querySelector('[name=vatMode]:checked').value,displayOptions:getDisplayOptions(),archiveId:window._openedArchiveId||null,rateFetchedAt:window._rateFetchedAt||null,rateSource:window._rateSource||'Manuel',savedAt:new Date().toISOString()}}
function saveDraftQuietly(){const key=draftKey();if(!key||document.body.classList.contains('view-mode'))return false;try{localStorage.setItem(key,JSON.stringify(collectDraft()));const st=document.getElementById('draftStatus');if(st)st.textContent='Taslak bu cihazda kaydedildi';return true}catch(e){const st=document.getElementById('draftStatus');if(st)st.textContent='Taslak kaydedilemedi';return false}}
function saveDraftDebounced(){clearTimeout(window._draftTimer);window._draftTimer=setTimeout(saveDraftQuietly,700)}
function clearDraft(){clearTimeout(window._draftTimer);try{const key=draftKey();if(key)localStorage.removeItem(key)}catch(e){}}
function restoreDraft(manual=false){try{const key=draftKey(),raw=key&&localStorage.getItem(key);if(!raw){if(manual)alert('Bu çalışma alanında kayıtlı taslak yok.');return false}const d=JSON.parse(raw);if(!Array.isArray(d.items))throw Error('Geçersiz taslak');if(!confirm('Bu cihazdaki '+new Date(d.savedAt).toLocaleString('tr-TR')+' tarihli taslak açılsın mı?'))return false;fields.forEach(id=>{if(d[id]!==undefined&&id!=='corpHex')document.getElementById(id).value=d[id]});document.getElementById('items').innerHTML='';d.items.forEach(addItem);setVatMode(d.vatMode);setDisplayOptions(d.displayOptions);window._openedArchiveId=d.archiveId;window._rateFetchedAt=d.rateFetchedAt;window._rateSource=d.rateSource;document.body.classList.remove('view-mode');closeAllProeraViews();updateValidity();render();return true}catch(e){alert('Taslak açılamadı: '+e.message);return false}}
