for(const [id,close] of Object.entries(overlayClosers)){const el=document.getElementById(id);el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-label',el.querySelector('h2,h3')?.textContent||'Bildirimler');el.addEventListener('click',e=>{if(e.target===el)close()})}
function activeDialog(){return Object.keys(overlayClosers).map(id=>document.getElementById(id)).filter(el=>getComputedStyle(el).display!=='none').sort((a,b)=>Number(getComputedStyle(b).zIndex)-Number(getComputedStyle(a).zIndex))[0]}
document.addEventListener('keydown',e=>{const drawer=document.getElementById('mobileNavToggle').checked;const dialog=drawer?document.getElementById('mobileDrawer'):activeDialog();if(e.key==='Escape'){if(drawer)setMobileMenu(false);else if(dialog)overlayClosers[dialog.id]();return}if(e.key==='Tab'&&dialog){const nodes=[...dialog.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(first&&(!dialog.contains(document.activeElement)||(e.shiftKey&&document.activeElement===first)||(!e.shiftKey&&document.activeElement===last))){e.preventDefault();(e.shiftKey?last:first).focus()}}});
document.getElementById('mobileNavToggle').addEventListener('change',e=>setMobileMenu(e.target.checked));
mobileNavigate=function(action){setMobileMenu(false);return appNavigate(action)};
const originalNavigate=appNavigate;appNavigate=function(action){document.querySelectorAll('.ds-nav button,.md-menu button').forEach(el=>{const active=el.getAttribute('onclick')?.includes("'"+action+"'");el.classList.toggle('active',!!active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});return originalNavigate(action)};
const oldOpenNav=openMobileNavFromLayer;openMobileNavFromLayer=function(){oldOpenNav();setMobileMenu(true)};
window.addEventListener('pagehide',()=>{if(window._draftTimer)saveDraftQuietly()});
labelControls();document.getElementById('mobileDrawer').inert=true;
new MutationObserver(records=>{for(const r of records)for(const node of r.addedNodes)if(node.nodeType===1)labelControls(node)}).observe(document.body,{childList:true,subtree:true});
const TURKEY_CITIES='Adana,Adıyaman,Afyonkarahisar,Ağrı,Amasya,Ankara,Antalya,Artvin,Aydın,Balıkesir,Bilecik,Bingöl,Bitlis,Bolu,Burdur,Bursa,Çanakkale,Çankırı,Çorum,Denizli,Diyarbakır,Edirne,Elazığ,Erzincan,Erzurum,Eskişehir,Gaziantep,Giresun,Gümüşhane,Hakkâri,Hatay,Isparta,Mersin,İstanbul,İzmir,Kars,Kastamonu,Kayseri,Kırklareli,Kırşehir,Kocaeli,Konya,Kütahya,Malatya,Manisa,Kahramanmaraş,Mardin,Muğla,Muş,Nevşehir,Niğde,Ordu,Rize,Sakarya,Samsun,Siirt,Sinop,Sivas,Tekirdağ,Tokat,Trabzon,Tunceli,Şanlıurfa,Uşak,Van,Yozgat,Zonguldak,Aksaray,Bayburt,Karaman,Kırıkkale,Batman,Şırnak,Bartın,Ardahan,Iğdır,Yalova,Karabük,Kilis,Osmaniye,Düzce'.split(',');
function initTurkeyCities(){document.getElementById('ciCity')?.setAttribute('aria-label','İl')}
function crmLocalDate(){return isoLocal(new Date())}
function reminderTone(date){return date<=crmLocalDate()?'today':date===isoLocal(new Date(new Date().setDate(new Date().getDate()+1)))?'due':''}
async function loadCrmReminders(){if(!sb||!currentUser||!currentCompanyId)return;const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const {data,error}=await sb.from('customer_interactions').select('id,company_name,contact_name,reminder_date,status').eq('company_id',currentCompanyId).eq('status','gorusuluyor').lte('reminder_date',isoLocal(tomorrow)).order('reminder_date').limit(100);const box=document.getElementById('crmReminderSummary');if(!box)return;if(error){box.textContent='Görüşme hatırlatmaları yüklenemedi.';return}box.innerHTML=(data||[]).map(x=>`<button type="button" class="reminder-badge ${reminderTone(x.reminder_date)}" onclick="openReminder(${Number(x.id)})">${esc(x.company_name||x.contact_name||'Görüşme')} · ${esc(x.reminder_date)}</button>`).join('')||'<span class="muted">Yaklaşan görüşme hatırlatması yok.</span>'}
async function openReminder(id){await openCrm();document.getElementById('crmMonth').value='';editInteraction(id);renderCrm()}
const guideSteps=[['Firma bilgileri','Ayarlar bölümünden firma bilgilerinizi, logonuzu ve banka hesaplarınızı ekleyin.'],['Müşteri ve ürünler','Müşteriler ve Ürün Kataloğu bölümlerinde tekliflerinizi hazırlarken kullanacağınız kayıtları oluşturun.'],['Proforma hazırlama','Yeni Proforma ile müşteriyi ve ürünleri seçin; para birimini, kuru ve KDV tercihini kontrol edin.'],['Kaydetme ve takip','Kaydet + PDF ile proformayı arşive kaydedin. Görüşmeler ve Takvim üzerinden işlerinizi takip edin.']];
let guideIndex=0;
function showGuideStep(){document.getElementById('guideTitle').textContent=guideSteps[guideIndex][0];document.getElementById('guideStep').textContent=guideSteps[guideIndex][1];document.getElementById('guideProgress').style.width=((guideIndex+1)/guideSteps.length*100)+'%'}
function openGuide(){guideIndex=0;showGuideStep();document.getElementById('guideOverlay').classList.add('open')}
function guidePrev(){guideIndex=Math.max(0,guideIndex-1);showGuideStep()}
function guideNext(){if(guideIndex===guideSteps.length-1){finishGuide();return}guideIndex++;showGuideStep()}
function finishGuide(){document.getElementById('guideOverlay').classList.remove('open')}

// Technical service module: cloud records scoped to the signed-in company.
const SERVICE_STATES={waiting:{label:'Beklemede',color:'#ffba24'},following:{label:'Takip Ediliyor',color:'#1683ff'},approved:{label:'Onaylandı',color:'#00bd8d'},completed:{label:'Tamamlandı',color:'#39bfd1'},failed:{label:'Yapılamadı',color:'#f4445d'}};
const SERVICE_FIELDS={svcDate:'received_date',svcStatus:'status',svcPriority:'priority',svcAssignee:'assigned_to',svcFollowUp:'follow_up_date',svcDelivery:'delivered_date',svcCustomer:'customer_name',svcContact:'contact_name',svcPhone:'phone',svcEmail:'email',svcAddress:'address',svcDevice:'device_name',svcBrand:'brand_model',svcSerial:'serial_number',svcWarranty:'warranty_status',svcAccessories:'accessories',svcFault:'reported_issue',svcDiagnosis:'diagnosis',svcWork:'work_performed',svcParts:'parts_used',svcNotes:'notes'};
let serviceRows=[],serviceCustomers=[],serviceEditing=null,serviceLoadToken=0,serviceDashToken=0,serviceBusy=false,serviceDirty=false,serviceSearchTimer;
function serviceState(status){return SERVICE_STATES[status]||{label:status||'Belirtilmedi',color:'#64748b'}}
function serviceBadge(status,pulse=false){const s=serviceState(status);return `<span class="service-badge ${pulse?'service-pulse':''}" style="--svc-color:${s.color}"><i aria-hidden="true"></i>${esc(s.label)}</span>`}
function serviceDate(value){return value?String(value).slice(0,10).split('-').reverse().join('.'):'—'}
function serviceError(error){if(['42P01','PGRST205'].includes(error?.code))return 'Teknik servis alanı henüz etkinleştirilmemiş. Servis kurulumu tamamlandığında bu alan kullanılabilir.';return 'Servis kayıtlarına ulaşılamadı. Bağlantınızı ve çalışma alanı yetkinizi kontrol edip tekrar deneyin.'}
function requireServiceSession(){if(!sb||!currentUser||!currentCompanyId){alert('Önce firma çalışma alanınıza giriş yapın.');return false}return true}
async function openServices(){if(!requireServiceSession())return;closeAllProeraViews();document.getElementById('serviceOverlay').classList.add('open');await loadServices()}
async function openServicesWithFilter(status){document.getElementById('serviceFilter').value=status;document.getElementById('serviceSearch').value='';return appNavigate('service')}
function searchFromDashboard(){const query=val('dashGlobalSearch').trim();if(hasAppAction('archive')){document.getElementById('archiveQuery').value=query;appNavigate('archive')}else if(hasAppAction('service')){document.getElementById('serviceSearch').value=query;document.getElementById('serviceFilter').value='';appNavigate('service')}}
function searchServicesFromDashboard(){if(!hasAppAction('service'))return;document.getElementById('serviceSearch').value=val('dashGlobalSearch');document.getElementById('serviceFilter').value='';appNavigate('service')}
function scheduleServiceSearch(){clearTimeout(serviceSearchTimer);serviceSearchTimer=setTimeout(loadServices,250)}
async function serviceCounts(){const states=Object.keys(SERVICE_STATES);const results=await Promise.all(states.map(status=>sb.from('technical_service_records').select('id',{count:'exact',head:true}).eq('company_id',currentCompanyId).eq('status',status)));const error=results.find(x=>x.error)?.error;if(error)throw error;return Object.fromEntries(states.map((key,i)=>[key,results[i].count||0]))}
function renderServiceSummary(counts){document.getElementById('serviceSummary').innerHTML=Object.keys(SERVICE_STATES).map(key=>`<button type="button" class="service-summary-card" data-service-filter="${key}" style="--svc-color:${SERVICE_STATES[key].color}"><span>${SERVICE_STATES[key].label}</span><b>${counts[key]}</b></button>`).join('');document.querySelectorAll('[data-service-filter]').forEach(b=>b.onclick=()=>{document.getElementById('serviceFilter').value=b.dataset.serviceFilter;loadServices()})}
async function loadServices(){if(!requireServiceSession())return;const token=++serviceLoadToken,company=currentCompanyId,state=document.getElementById('serviceLoadState');state.textContent='Servis kayıtları yükleniyor…';try{let query=sb.from('technical_service_records').select('*').eq('company_id',company).order('updated_at',{ascending:false}).limit(100);const status=val('serviceFilter');if(status==='active')query=query.in('status',['waiting','following','approved']);else if(status)query=query.eq('status',status);const q=val('serviceSearch').trim().replace(/[,%_()."\\]/g,' ').trim().slice(0,100);if(q)query=query.or(['service_number','customer_name','device_name','brand_model','serial_number','assigned_to'].map(k=>k+'.ilike.%'+q+'%').join(','));const [result,counts]=await Promise.all([query,serviceCounts()]);if(token!==serviceLoadToken||company!==currentCompanyId)return;if(result.error)throw result.error;serviceRows=result.data||[];renderServiceList();renderServiceSummary(counts);state.textContent=serviceRows.length===100?'En güncel 100 eşleşme gösteriliyor. Daha eski kayıtlar için aramanızı daraltın.':serviceRows.length+' servis kaydı';}catch(e){if(token!==serviceLoadToken)return;serviceRows=[];document.getElementById('serviceList').innerHTML='';document.getElementById('serviceSummary').innerHTML='';state.textContent=serviceError(e);console.warn('Service load',e)}}
function renderServiceList(){const box=document.getElementById('serviceList');box.innerHTML=serviceRows.map(row=>`<article class="service-record" style="--svc-color:${serviceState(row.status).color}"><div class="service-record-top"><div><span class="service-number">${esc(row.service_number)}</span><h3>${esc(row.device_name)}</h3><p>${esc(row.customer_name)}</p></div>${serviceBadge(row.status)} </div><div class="service-record-meta"><span><small>Seri no</small>${esc(row.serial_number||'Belirtilmedi')}</span><span><small>Servis sorumlusu</small>${esc(row.assigned_to||'Atanmadı')}</span><span><small>Kabul tarihi</small>${serviceDate(row.received_date)}</span><span><small>Sonraki takip</small>${serviceDate(row.follow_up_date)}</span></div><p class="service-issue">${esc(row.reported_issue)}</p><div class="service-record-bottom"><span class="${row.priority==='urgent'?'service-urgent':'muted'}">${row.priority==='urgent'?'Acil servis':'Normal öncelik'}</span><button type="button" class="btn light" data-service-open="${esc(row.id)}">Formu Aç / Düzenle →</button></div></article>`).join('')||'<div class="service-empty"><b>Servis kaydı bulunamadı.</b><p>Yeni servis formu oluşturabilir veya filtreyi değiştirebilirsiniz.</p><button class="btn primary" onclick="newServiceRecord()">+ Yeni Servis Formu</button></div>';bindServiceLinks(box)}
function bindServiceLinks(root){root.querySelectorAll('[data-service-open]').forEach(b=>b.onclick=()=>editServiceRecord(b.dataset.serviceOpen))}
async function refreshServiceDashboard(){if(!sb||!currentUser||!currentCompanyId)return;const token=++serviceDashToken,company=currentCompanyId,box=document.getElementById('dashServiceStatus');try{const [counts,recent]=await Promise.all([serviceCounts(),sb.from('technical_service_records').select('id,service_number,device_name,customer_name,status,received_date,follow_up_date').eq('company_id',company).order('updated_at',{ascending:false}).limit(3)]);if(token!==serviceDashToken||company!==currentCompanyId)return;if(recent.error)throw recent.error;const total=Object.values(counts).reduce((a,b)=>a+b,0);document.getElementById('dashActiveServices').textContent=counts.waiting+counts.following+counts.approved;let offset=0;const stops=Object.keys(SERVICE_STATES).map(key=>{const start=offset;offset+=total?counts[key]/total*100:0;return `${SERVICE_STATES[key].color} ${start}% ${offset}%`});box.innerHTML=`<div class="service-donut-layout"><div class="service-donut" style="background:${total?'conic-gradient('+stops.join(',')+')':'#e8edf5'}" aria-label="${total} servis kaydı"><div><b>${total}</b><small>Toplam Kayıt</small></div></div><div class="service-legend">${Object.keys(SERVICE_STATES).map(k=>`<button type="button" data-service-status="${k}" style="--svc-color:${SERVICE_STATES[k].color}" class="${counts[k]&&k==='waiting'?'service-pulse':''}"><span><i></i>${SERVICE_STATES[k].label}</span><b>${counts[k]}</b></button>`).join('')}</div></div>`;box.querySelectorAll('[data-service-status]').forEach(b=>b.onclick=()=>openServicesWithFilter(b.dataset.serviceStatus));const list=document.getElementById('dashServiceRecent');list.innerHTML=(recent.data||[]).map(r=>`<button class="service-recent-row" type="button" data-service-open="${esc(r.id)}"><span><b>${esc(r.service_number)}</b><small>${esc(r.device_name)}</small></span>${serviceBadge(r.status,r.status==='waiting'||(!['completed','failed'].includes(r.status)&&r.follow_up_date&&r.follow_up_date<isoLocal(new Date())))}</button>`).join('')||'<p class="muted">Henüz servis kaydı yok.</p>';bindServiceLinks(list)}catch(e){if(token!==serviceDashToken)return;document.getElementById('dashActiveServices').textContent='—';box.innerHTML='<p class="service-error">'+esc(serviceError(e))+'</p>';document.getElementById('dashServiceRecent').innerHTML='<button class="text-action" onclick="refreshServiceDashboard()">Tekrar dene</button>'}}
async function loadServiceCustomers(){const select=document.getElementById('svcCustomerPicker');select.innerHTML='<option value="">Müşteri bilgilerini elle gir</option>';try{const {data,error}=await sb.from('customers').select('id,name,phone,email,address').eq('company_id',currentCompanyId).order('name').limit(500);if(error)throw error;serviceCustomers=data||[];serviceCustomers.forEach(c=>select.add(new Option(c.name,String(c.id))))}catch(e){serviceCustomers=[];select.innerHTML='<option value="">Müşteri listesi alınamadı; elle girebilirsiniz</option>'}}
function selectServiceCustomer(id){const c=serviceCustomers.find(x=>String(x.id)===id);if(!c)return;document.getElementById('svcCustomer').value=c.name||'';document.getElementById('svcPhone').value=c.phone||'';document.getElementById('svcEmail').value=c.email||'';document.getElementById('svcAddress').value=c.address||'';serviceDirty=true}
function fillServiceForm(record=null){serviceEditing=record;serviceDirty=false;document.getElementById('serviceForm').reset();document.getElementById('svcId').value=record?.id||'';document.getElementById('svcVersion').value=record?.updated_at||'';Object.entries(SERVICE_FIELDS).forEach(([id,key])=>{if(record&&record[key]!=null)document.getElementById(id).value=record[key]});if(!record){document.getElementById('svcDate').value=isoLocal(new Date());document.getElementById('svcAssignee').value=currentUser?.user_metadata?.full_name||''}document.getElementById('svcNumber').textContent=record?.service_number||'Kayıt sonrası oluşturulur';document.getElementById('serviceFormTitle').textContent=record?'Servis formunu düzenle':'Yeni servis kaydı';document.getElementById('serviceSaveState').textContent='';document.getElementById('serviceHistory').textContent=record?'Durum geçmişi yükleniyor…':'İlk kayıt sonrası burada gösterilir.';document.getElementById('serviceFormModal').classList.add('open');document.querySelector('.service-form-card').scrollTop=0;document.getElementById('svcDate').focus({preventScroll:true})}
async function newServiceRecord(){if(!requireServiceSession())return;if(document.getElementById('serviceFormModal').classList.contains('open')&&!closeServiceForm())return;fillServiceForm();await loadServiceCustomers()}
async function editServiceRecord(id){if(!requireServiceSession())return;if(document.getElementById('serviceFormModal').classList.contains('open')&&!closeServiceForm())return;try{const {data,error}=await sb.from('technical_service_records').select('*').eq('company_id',currentCompanyId).eq('id',id).single();if(error||!data)throw error||Error('Kayıt bulunamadı');fillServiceForm(data);await Promise.all([loadServiceCustomers(),loadServiceHistory(id)])}catch(e){alert('Servis formu açılamadı. '+serviceError(e))}}
function closeServiceForm(){if(serviceBusy)return false;if(serviceDirty&&!confirm('Kaydedilmemiş servis formu değişiklikleri kapatılsın mı?'))return false;document.getElementById('serviceFormModal').classList.remove('open');serviceDirty=false;return true}
function servicePayload(){const payload={company_id:currentCompanyId};Object.entries(SERVICE_FIELDS).forEach(([id,key])=>{const v=val(id).trim();payload[key]=['follow_up_date','delivered_date'].includes(key)?v||null:v});return payload}
async function saveServiceRecord(){if(serviceBusy||!requireServiceSession())return;const form=document.getElementById('serviceForm');if(!form.reportValidity())return;const payload=servicePayload();if(!payload.customer_name||!payload.device_name||!payload.reported_issue){alert('Müşteri, cihaz ve arıza bilgilerini doldurun.');return}if(['completed','failed'].includes(payload.status)&&!payload.work_performed){alert('Yapılan işlemi veya yapılamama nedenini yazın.');document.getElementById('svcWork').focus();return}if(payload.delivered_date&&payload.delivered_date<payload.received_date){alert('Teslim tarihi kabul tarihinden önce olamaz.');return}const state=document.getElementById('serviceSaveState'),button=document.getElementById('serviceSaveBtn');serviceBusy=true;button.disabled=true;state.textContent='Kaydediliyor…';try{const id=val('svcId');let query=id?sb.from('technical_service_records').update(payload).eq('company_id',currentCompanyId).eq('id',id).eq('updated_at',val('svcVersion')):sb.from('technical_service_records').insert(payload);const {data,error}=await query.select().maybeSingle();if(error)throw error;if(!data)throw Error('Bu kayıt başka bir kullanıcı tarafından değiştirilmiş olabilir. Formu kapatıp yeniden açın.');serviceEditing=data;serviceDirty=false;document.getElementById('svcId').value=data.id;document.getElementById('svcVersion').value=data.updated_at;document.getElementById('svcNumber').textContent=data.service_number;document.getElementById('serviceFormTitle').textContent='Servis formunu düzenle';state.textContent='✓ Servis kaydı buluta kaydedildi.';await loadServiceHistory(data.id);await refreshServiceDashboard();if(document.getElementById('serviceOverlay').classList.contains('open'))await loadServices()}catch(e){state.textContent='Kayıt tamamlanamadı. '+(e?.message||serviceError(e));console.warn('Service save',e)}finally{serviceBusy=false;button.disabled=false}}
async function loadServiceHistory(id){const box=document.getElementById('serviceHistory');try{const {data,error}=await sb.from('technical_service_history').select('old_status,new_status,changed_at').eq('service_id',id).order('changed_at',{ascending:false}).limit(50);if(error)throw error;box.innerHTML=(data||[]).map(r=>`<div><time>${new Date(r.changed_at).toLocaleString('tr-TR')}</time><span>${r.old_status?esc(serviceState(r.old_status).label)+' → ':'Kayıt açıldı → '}${esc(serviceState(r.new_status).label)}</span></div>`).join('')||'<span class="muted">Henüz durum değişikliği yok.</span>'}catch(e){box.textContent='Durum geçmişi yüklenemedi.'}}
function servicePrintExcerpt(value,limit=190){
 const text=String(value||'').trim();
 if(!text)return '—';
 if(text.length<=limit)return text;
 return text.slice(0,limit).trimEnd()+'… (tam metin dijital kayıtta)';
}
function buildServicePrint(){
 const p=servicePayload(),s=window._companySettings||{},logo=window._companyLogo||s.logo_data||'';
 const accent=/^#[0-9a-f]{6}$/i.test(s.corporate_color||'')?s.corporate_color:'#174a78';
 const field=(title,value)=>`<div class="svc-a4-field"><dt>${title}</dt><dd>${esc(value||'—')}</dd></div>`;
 const section=(title,value,limit)=>`<section class="svc-a4-section"><h3>${title}</h3><p>${esc(servicePrintExcerpt(value,limit))}</p></section>`;
 const company=s.company_display_name||s.legal_name||currentMembership?.companies?.name||'Firma';
 document.getElementById('servicePrintArea').innerHTML=`<article class="svc-a4" style="--service-print-accent:${accent}">
   <header class="svc-a4-header">
     <div class="svc-a4-brand">${logo?`<img src="${esc(logo)}" alt="${esc(company)} logosu">`:`<strong>${esc(company)}</strong>`}<div><span>${esc([s.address,s.phone,s.email].filter(Boolean).join(' · '))}</span></div></div>
     <div class="svc-a4-document"><h1>TEKNİK SERVİS FORMU</h1>${serviceEditing?.service_number?`<strong>${esc(serviceEditing.service_number)}</strong>`:''}<span>Kabul tarihi: ${esc(serviceDate(p.received_date))}</span></div>
   </header>
   <div class="svc-a4-stripe"><span>Servis ve teslim kayıt formu</span><b>${esc(serviceState(p.status).label)}</b></div>
   <div class="svc-a4-cards">
     <section class="svc-a4-card"><h2>01 &nbsp; MÜŞTERİ BİLGİLERİ</h2><dl>${field('Firma / Klinik',p.customer_name)}${field('İlgili kişi',p.contact_name)}${field('Telefon',p.phone)}${field('E-posta',p.email)}${field('Adres',servicePrintExcerpt(p.address,110))}</dl></section>
     <section class="svc-a4-card"><h2>02 &nbsp; CİHAZ VE SERVİS</h2><dl>${field('Cihaz',p.device_name)}${field('Marka / Model',p.brand_model)}${field('Seri numarası',p.serial_number)}${field('Garanti',p.warranty_status)}${field('Servis sorumlusu',p.assigned_to)}${field('Takip / Teslim',`${serviceDate(p.follow_up_date)} / ${serviceDate(p.delivered_date)}`)}</dl></section>
   </div>
   <div class="svc-a4-work"><h2>03 &nbsp; SERVİS İŞLEM DETAYI</h2>
     <div class="svc-a4-work-grid">${section('Teslim alınan aksesuarlar / fiziksel durum',p.accessories,130)}${section('Bildirilen arıza / talep',p.reported_issue,220)}${section('Teknik tespit / teşhis',p.diagnosis,230)}${section('Yapılan işlem / yapılamama nedeni',p.work_performed,260)}${section('Kullanılan / değiştirilen parçalar',p.parts_used,155)}${section('Notlar ve öneriler',p.notes,155)}</div>
   </div>
   <div class="svc-a4-signatures"><div><b>Servis Yetkilisi</b><span>Ad Soyad / İmza</span></div><div><b>Müşteri / Teslim Alan</b><span>Ad Soyad / İmza</span></div></div>
   <footer class="svc-a4-footer"><span>Bu belge teknik servis işlem ve teslim kaydıdır.${serviceDirty?' · Kaydedilmemiş değişiklikler içerir.':''}</span><span>${esc(serviceEditing?.service_number||'Teknik Servis')}</span></footer>
 </article>`;
}

async function printServiceForm(){buildServicePrint();const imgs=[...document.querySelectorAll('#servicePrintArea img')];await Promise.all(imgs.map(img=>img.decode?.().catch(()=>{})));window._servicePrintTitle=document.title;document.title='';document.body.classList.add('printing-service');window.print()}
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-service');if(window._servicePrintTitle){document.title=window._servicePrintTitle;delete window._servicePrintTitle}});
document.getElementById('serviceForm').addEventListener('input',()=>serviceDirty=true);document.getElementById('serviceForm').addEventListener('change',()=>serviceDirty=true);
