let auditPage=0,auditRequest=0,auditRows=[];
function auditCanRead(){return !!currentUser&&['owner','admin'].includes(currentMembership?.role)}
function auditTime(value){return value?new Date(value).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}):'—'}
function auditValue(v,key){if(v===undefined||v===null)return '—';if(v?.kind==='image_fingerprint')return 'Görsel kimlik özeti (SHA-256): '+v.sha256;if(key==='approval_state')return {draft:'Taslak',pending:'Onay bekliyor',approved:'Onaylandı',revision:'Revizyon istendi',legacy:'Eski kayıt'}[v]||String(v);if(key==='role')return {owner:'Şirket Sahibi',...teamRoles}[v]||String(v);if(typeof v==='string'&&key.endsWith('_at')&&!isNaN(Date.parse(v)))return auditTime(v);return typeof v==='object'?JSON.stringify(v,null,2):String(v)}
function showAuditDetail(id){if(!auditCanRead())return;const row=auditRows.find(x=>String(x.id)===String(id));if(!row)return;uiOpenDrawer('İşlem ayrıntısı · '+(row.record_label||row.record_id||''));const before=row.old_data||{},after=row.new_data||{},keys=row.changed_fields?.length?row.changed_fields:[...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>JSON.stringify(before[k])!==JSON.stringify(after[k]));document.getElementById('uiDrawerBody').innerHTML=`<p><b>${esc(auditEventLabels[row.event_key]||row.action)}</b></p><p>${esc(row.actor_name||row.actor_email||'Sistem / otomatik işlem')} · ${esc(row.actor_email||'')}<br>${esc(auditTime(row.created_at))} · ${esc(auditTableLabels[row.table_name]||row.table_name)}</p><p class="muted">İşlem #${esc(row.id)} · Kayıt ${esc(row.record_id||'—')}</p><div class="audit-detail-table"><table><thead><tr><th>Alan</th><th>Önceki değer</th><th>Yeni değer</th></tr></thead><tbody>${keys.map(k=>`<tr><th>${esc(auditFieldLabels[k]||k)}</th><td><pre>${esc(auditValue(before[k],k))}</pre></td><td><pre>${esc(auditValue(after[k],k))}</pre></td></tr>`).join('')||'<tr><td colspan="3">Eski kayıtta ayrıntı bulunmuyor.</td></tr>'}</tbody></table></div>`}
async function loadAuditHistory(reset=true){const list=document.getElementById('auditHistoryList');if(!list)return;if(!auditCanRead()){auditRows=[];list.replaceChildren();document.getElementById('auditHistoryCard').hidden=true;return}if(reset)auditPage=0;const token=++auditRequest,company=currentCompanyId;list.textContent='İşlem geçmişi yükleniyor…';try{let q=sb.from('audit_logs').select('id,company_id,created_at,actor_email,actor_name,actor_role,user_id,table_name,record_id,record_label,event_key,action,changed_fields,old_data,new_data',{count:'exact'}).eq('company_id',company).order('created_at',{ascending:false}).order('id',{ascending:false});const user=val('auditUser').trim(),record=val('auditRecord').trim(),module=val('auditModule'),event=val('auditEvent'),from=val('auditFrom'),to=val('auditTo');if(from&&to&&from>to)throw Error('Başlangıç tarihi bitişten sonra olamaz.');const pattern=v=>'%'+v.replace(/[\\%_]/g,'\\$&')+'%';if(user)q=q.ilike('actor_email',pattern(user));if(record)q=q.ilike('record_label',pattern(record));if(module)q=q.eq('table_name',module);if(event)q=q.eq('event_key',event);if(from)q=q.gte('created_at',new Date(from+'T00:00:00+03:00').toISOString());if(to)q=q.lt('created_at',new Date(new Date(to+'T00:00:00+03:00').getTime()+86400000).toISOString());const {data,error,count}=await q.range(auditPage*50,auditPage*50+49);if(token!==auditRequest||company!==currentCompanyId||!auditCanRead())return;if(error)throw error;auditRows=data||[];list.innerHTML=`<div class="audit-table-wrap"><table class="audit-table"><thead><tr><th>Tarih / Saat</th><th>Kullanıcı</th><th>Bölüm / Kayıt</th><th>İşlem</th><th></th></tr></thead><tbody>${auditRows.map(r=>`<tr><td>${esc(auditTime(r.created_at))}</td><td><b>${esc(r.actor_name||r.actor_email||'Sistem / otomatik işlem')}</b><small>${esc(r.actor_email||'')}</small><span class="audit-role">${esc(({owner:'Şirket Sahibi',...teamRoles})[r.actor_role]||(!r.user_id?'Sistem':'Eski kayıt'))}</span></td><td><b>${esc(auditTableLabels[r.table_name]||r.table_name)}</b><small>${esc(r.record_label||r.record_id||'—')}</small></td><td><span class="audit-event ${r.event_key==='proforma_approved_signed'?'audit-approved':r.action==='DELETE'||r.event_key==='record_soft_deleted'?'audit-deleted':''}">${esc(auditEventLabels[r.event_key]||r.action)}</span></td><td><button type="button" class="btn light" onclick="showAuditDetail(${Number(r.id)})">Ayrıntı</button></td></tr>`).join('')||'<tr><td colspan="5">Bu filtrelerle eşleşen işlem bulunmuyor.</td></tr>'}</tbody></table></div>`;document.getElementById('auditPageText').textContent='Sayfa '+(auditPage+1)+' · '+(count??auditRows.length)+' kayıt';document.getElementById('auditPrev').disabled=auditPage===0;document.getElementById('auditNext').disabled=(auditPage+1)*50>=(count??auditRows.length)}catch(e){if(token===auditRequest)list.textContent='İşlem geçmişi yüklenemedi: '+e.message}}
function auditNextPage(direction){auditPage=Math.max(0,auditPage+direction);loadAuditHistory(false)}
(function(){const body=document.querySelector('#settingsOverlay .settings-body'),tabs=document.getElementById('uiSettingsTabs');if(!body||!tabs)return;const card=document.createElement('section');card.id='auditHistoryCard';card.className='settings-card';card.hidden=true;card.innerHTML=`<h3>İşlem Geçmişi</h3><p class="hint">Şirket sahibi ve yöneticiler dahil tüm kullanıcıların kayıt değişiklikleri. Bu ekran yalnızca okunabilir; loglar değiştirilemez veya silinemez. Saatler Türkiye saatidir.</p><div class="audit-filters"><div><label for="auditUser">Kullanıcı e-postası</label><input id="auditUser" type="search" placeholder="E-posta ile filtrele"></div><div><label for="auditRecord">Kayıt / proforma</label><input id="auditRecord" type="search" placeholder="Numara veya kayıt adı"></div><div><label for="auditModule">Bölüm</label><select id="auditModule"><option value="">Tüm bölümler</option>${Object.entries(auditTableLabels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div><div><label for="auditEvent">İşlem</label><select id="auditEvent"><option value="">Tüm işlemler</option>${Object.entries(auditEventLabels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div><div><label for="auditFrom">Başlangıç tarihi</label><input id="auditFrom" type="date"></div><div><label for="auditTo">Bitiş tarihi</label><input id="auditTo" type="date"></div></div><div class="actions"><button type="button" class="btn primary" onclick="loadAuditHistory()">Filtrele / Yenile</button></div><div id="auditHistoryList" aria-live="polite"></div><div class="audit-paging"><button type="button" id="auditPrev" class="btn light" onclick="auditNextPage(-1)" disabled>Önceki</button><span id="auditPageText"></span><button type="button" id="auditNext" class="btn light" onclick="auditNextPage(1)" disabled>Sonraki</button></div>`;body.append(card);const button=document.createElement('button');button.type='button';button.dataset.key='audit';button.textContent='İşlem Geçmişi';button.setAttribute('aria-pressed','false');button.hidden=true;tabs.append(button);tabs.addEventListener('click',e=>{if(e.target.closest('button')!==button)card.hidden=true});button.onclick=()=>{if(!auditCanRead())return;uiSettingsCards.forEach(c=>c.hidden=true);document.getElementById('signingAssetsCard').hidden=true;document.getElementById('uiSettingsPreview').hidden=true;card.hidden=false;uiSelect('uiSettingsTabs','audit');loadAuditHistory()};const baseRoles=applyRoleNavigation;applyRoleNavigation=function(){baseRoles();button.hidden=!auditCanRead();if(!auditCanRead()){++auditRequest;auditRows=[];card.hidden=true;document.getElementById('auditHistoryList').replaceChildren()}};const baseOpen=openSettings;openSettings=async function(){card.hidden=true;button.hidden=!auditCanRead();await baseOpen()};})();

// Company-scoped upcoming agenda and in-site reminders.
let agendaDays=7,agendaRows=[],agendaCompany=null,agendaVersion=0;
function agendaToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date())}
function agendaDateAdd(date,n){const d=new Date(date+'T12:00:00+03:00');d.setUTCDate(d.getUTCDate()+n);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(d)}
function agendaStart(x){return new Date(calendarDate(x.event_date)+'T'+String(x.start_time||'09:00').slice(0,5)+':00+03:00').getTime()}
function agendaTone(x){if(x.completed_at)return ['done','Tamamlandı'];const delta=agendaStart(x)-Date.now();if(delta<0)return ['late','Gecikti'];if(delta<=86400000)return ['soon','24 saat içinde'];return [calendarDate(x.event_date)===agendaToday()?'today':'future',calendarDate(x.event_date)===agendaToday()?'Bugün':Math.round((new Date(calendarDate(x.event_date)+'T12:00:00+03:00')-new Date(agendaToday()+'T12:00:00+03:00'))/86400000)+' gün sonra']}
function agendaCanWrite(){return ['owner','admin','manager','sales','service','call_center'].includes(currentMembership?.role)}
function agendaRow(x){const [tone,label]=agendaTone(x);return `<div class="agenda-row agenda-${tone}"><button type="button" class="agenda-open" data-agenda-open="${esc(x.id)}"><span class="agenda-date">${esc(new Date(calendarDate(x.event_date)+'T12:00:00+03:00').toLocaleDateString('tr-TR',{day:'numeric',month:'short',timeZone:'Europe/Istanbul'}))}<b>${esc(String(x.start_time||'').slice(0,5)||'Tüm gün')}</b></span><span><strong>${esc(x.title)}</strong><small>${esc([x.city,x.personnel,x.location].filter(Boolean).join(' · '))}</small><span class="agenda-status">${esc(label)}</span></span></button>${agendaCanWrite()?`<button type="button" class="btn light" data-agenda-complete="${esc(x.id)}">${x.completed_at?'Geri al':'Tamamlandı'}</button>`:''}</div>`}
function agendaBind(root){root.querySelectorAll('[data-agenda-open]').forEach(b=>b.onclick=()=>openAgendaEvent(b.dataset.agendaOpen));root.querySelectorAll('[data-agenda-complete]').forEach(b=>b.onclick=()=>completeAgendaEvent(b.dataset.agendaComplete,b))}
function renderAgenda(){if(agendaCompany!==currentCompanyId||!currentUser)return;const today=agendaToday(),end=agendaDateAdd(today,agendaDays-1),shown=agendaRows.filter(x=>calendarDate(x.event_date)>=today&&calendarDate(x.event_date)<=end);const box=document.getElementById('dashTodaySchedule');box.innerHTML=shown.map(agendaRow).join('')||'<p class="muted">Bu tarih aralığında randevu bulunmuyor.</p>';agendaBind(box);const overdue=agendaRows.filter(x=>!x.completed_at&&calendarDate(x.event_date)<today);document.getElementById('agendaOverdue').innerHTML=overdue.length?`<details><summary>${overdue.length} tamamlanmamış geçmiş randevu (son 30 gün)</summary>${overdue.map(agendaRow).join('')}</details>`:'';agendaBind(document.getElementById('agendaOverdue'));document.getElementById('dashTodayDate').textContent=agendaDays===1?'Bugünün randevuları':`Bugün dahil önümüzdeki ${agendaDays} gün`;renderAgendaReminder()}
function renderAgendaReminder(){const box=document.getElementById('agendaReminderList');if(!box)return;if(!currentUser||agendaCompany!==currentCompanyId){document.getElementById('agendaBell').hidden=true;box.replaceChildren();return}const now=Date.now();const due=agendaRows.filter(x=>!x.completed_at&&Number(x.reminder_minutes)>0&&agendaStart(x)>now&&agendaStart(x)-now<=Number(x.reminder_minutes)*60000);document.getElementById('agendaBell').hidden=false;document.getElementById('agendaBellCount').textContent=due.length;box.innerHTML=due.map(agendaRow).join('')||'<p class="muted">Şu anda zamanı gelen hatırlatma yok.</p>';agendaBind(box)}
async function loadAgenda(){if(!sb||!currentUser||!currentCompanyId){agendaRows=[];agendaCompany=null;renderAgendaReminder();return}const company=currentCompanyId,version=++agendaVersion;agendaCompany=null;document.getElementById('dashTodaySchedule').textContent='Randevular yükleniyor…';document.getElementById('agendaOverdue').replaceChildren();renderAgendaReminder();try{const {data,error}=await sb.from('calendar_events').select('*').eq('company_id',company).gte('event_date',agendaDateAdd(agendaToday(),-30)).lte('event_date',agendaDateAdd(agendaToday(),29)).order('event_date').order('start_time');if(version!==agendaVersion||company!==currentCompanyId||!currentUser)return;if(error)throw error;agendaRows=data||[];agendaCompany=company;renderAgenda()}catch(e){if(version===agendaVersion)document.getElementById('dashTodaySchedule').textContent='Randevular yüklenemedi: '+e.message}}
async function openAgendaEvent(id){if(agendaCompany!==currentCompanyId)return;const x=agendaRows.find(x=>String(x.id)===String(id));if(!x)return;document.getElementById('agendaReminderPanel').hidden=true;const d=calendarDate(x.event_date).split('-').map(Number);calendarCursor=new Date(d[0],d[1]-1,d[2]);await openCalendar();if(!calendarEvents.some(r=>String(r.id)===String(id)))calendarEvents.push(x);editCalendarEvent(id)}
async function completeAgendaEvent(id,button){if(!agendaCanWrite()||agendaCompany!==currentCompanyId)return;const x=agendaRows.find(r=>String(r.id)===String(id));if(!x)return;button.disabled=true;const company=currentCompanyId;try{const {data,error}=await sb.from('calendar_events').update({completed_at:x.completed_at?null:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('company_id',company).eq('id',id).select('id');if(error)throw error;if(!data?.length)throw Error('Kayıt değiştirilemedi.');if(company!==currentCompanyId)return;await loadAgenda();if(document.getElementById('calendarOverlay').classList.contains('open'))await loadCalendar()}catch(e){alert('Randevu güncellenemedi: '+e.message)}finally{button.disabled=false}}
(function(){const section=document.getElementById('dashTodaySchedule').closest('section');section.querySelector('h3').textContent='Yaklaşan Randevular';const controls=document.createElement('div');controls.className='agenda-filters';controls.innerHTML='<button type="button" data-days="1">Bugün</button><button type="button" data-days="7" aria-pressed="true">7 gün</button><button type="button" data-days="30">30 gün</button>';section.querySelector('.dash-panel-head').after(controls);controls.querySelectorAll('button').forEach(b=>b.onclick=()=>{agendaDays=Number(b.dataset.days);controls.querySelectorAll('button').forEach(v=>v.setAttribute('aria-pressed',String(v===b)));renderAgenda()});const overdue=document.createElement('div');overdue.id='agendaOverdue';section.append(overdue);const bell=document.createElement('button');bell.id='agendaBell';bell.className='agenda-bell';bell.type='button';bell.hidden=true;bell.innerHTML='🔔 Randevular <b id="agendaBellCount">0</b>';bell.onclick=()=>{renderAgendaReminder();document.getElementById('agendaReminderPanel').hidden=!document.getElementById('agendaReminderPanel').hidden};const panel=document.createElement('section');panel.id='agendaReminderPanel';panel.className='agenda-reminder-panel';panel.hidden=true;panel.innerHTML='<div class="dash-panel-head"><h3>Randevu Hatırlatmaları</h3><button type="button" class="btn light" onclick="document.getElementById(\'agendaReminderPanel\').hidden=true">Kapat</button></div><p class="muted">Site açıkken güncellenir. Tüm gün etkinlikleri için saat 09:00 esas alınır.</p><div id="agendaReminderList"></div>';document.body.append(bell,panel);const field=document.createElement('div');field.innerHTML='<label for="calReminder">Hatırlat</label><select id="calReminder"><option value="1440">1 gün önce</option><option value="60">1 saat önce</option><option value="15">15 dakika önce</option><option value="0">Hatırlatma kapalı</option></select>';document.querySelector('.calendar-form').append(field);const done=document.createElement('div');done.innerHTML='<label for="calCompleted">Randevu durumu</label><select id="calCompleted"><option value="">Planlandı</option><option value="done">Tamamlandı</option></select>';document.querySelector('.calendar-form').append(done);})();
const agendaNewBase=newCalendarEvent;newCalendarEvent=function(date){agendaNewBase(date);document.getElementById('calReminder').value='1440';document.getElementById('calCompleted').value=''};
const agendaEditBase=editCalendarEvent;editCalendarEvent=function(id){agendaEditBase(id);const x=calendarEvents.find(r=>String(r.id)===String(id));if(!x)return;document.getElementById('calReminder').value=String(x.reminder_minutes??1440);document.getElementById('calCompleted').value=x.completed_at?'done':''};
const agendaOpsBase=loadDashboardOperations;loadDashboardOperations=async function(){await Promise.allSettled([agendaOpsBase(),loadAgenda()]);renderAgenda()};
const agendaDeleteBase=deleteCalendarEvent;deleteCalendarEvent=async function(){await agendaDeleteBase();await loadAgenda()};
uiCalendarMode='week';uiSelect('uiCalendarSwitch','week');
const agendaRenderBase=renderCalendar;renderCalendar=function(){agendaRenderBase();document.querySelectorAll('#calendarGrid [data-event-id]').forEach(b=>{const x=calendarEvents.find(r=>String(r.id)===String(b.dataset.eventId));if(!x)return;const [tone,label]=agendaTone(x);b.classList.add('agenda-'+tone);const s=document.createElement('span');s.className='agenda-status';s.textContent=label;b.append(s)})};
