function fillOfferEditor(p){const c=p.customer_snapshot||{};document.getElementById('buyerCity').value=c.city||'';document.getElementById('date').value=p.proforma_date||'';no.value=p.proforma_number||'';buyerName.value=p.customer_name||c.name||'';buyerAddress.value=c.address||'';buyerTaxOffice.value=c.tax_office||'';buyerTaxNo.value=c.tax_number||'';buyerPhone.value=c.phone||'';buyerEmail.value=c.email||'';document.getElementById('delivery').value=c.delivery||'';currency.value=p.currency||'€';window._rateCurrency=val('currency');rate.value=p.exchange_rate??'';payment.value=p.payment_terms||'';bidder.value=p.bidder||'';notes.value=p.notes||'';document.getElementById('status').value=statusLabel(p.status);window._loadedStatus=document.getElementById('status').value;window._loadedStatusChangedAt=p.status_changed_at||null;validityDays.value=String(p.validity_days||7);window._rateFetchedAt=p.rate_fetched_at||null;window._rateSource=p.rate_source||'Kayıtlı kur';window._openedArchiveId=null;document.getElementById('bankEditors').innerHTML='';(p.bank_accounts||[]).forEach(b=>addBank({...b,id:undefined}));setVatMode(p.vat_mode||'excluded');setDisplayOptions(p.display_options||{});updateValidity();document.getElementById('rateStatus').textContent='🔒 Kayıtlı kur • '+(p.rate_source||'');document.getElementById('items').innerHTML='';(p.items||[]).forEach(r=>addItem({product_id:r.product_id,desc:r.description||r.desc,product_code:r.product_code||'',gtip:r.gtip,brand:r.brand,origin:r.origin,model:r.model,serial:r.serial,qty:r.qty,price:r.price,vat:r.vat,currency_conversion:r.currency_conversion}));if(!(p.items||[]).length)addItem();}
function buildOfferPayload(){const customer={city:val('buyerCity'),name:val('buyerName'),address:val('buyerAddress'),tax_office:val('buyerTaxOffice'),tax_number:val('buyerTaxNo'),phone:val('buyerPhone'),email:val('buyerEmail'),delivery:val('delivery')};const rows=[...document.querySelectorAll('.item')].map(x=>({product_id:x.dataset.productId||null,currency_conversion:readItemConversion(x),description:x.querySelector('.desc').value,product_code:x.dataset.productCode||'',gtip:x.querySelector('.gtip')?.value||'',brand:x.querySelector('.pbrand')?.value||'',origin:x.querySelector('.porigin')?.value||'',model:x.querySelector('.pmodel')?.value||'',serial:x.querySelector('.pserial')?.value||'',qty:+x.querySelector('.qty').value||0,price:parseTrNumber(x.querySelector('.price').value),vat:+x.querySelector('.vat').value||0}));const vatMode=document.querySelector('input[name=vatMode]:checked')?.value||'excluded';const subtotal=rows.reduce((a,r)=>a+(vatMode==='included'?r.qty*r.price/(1+r.vat/100):r.qty*r.price),0),vat_total=rows.reduce((a,r)=>a+(vatMode==='included'?r.qty*r.price-r.qty*r.price/(1+r.vat/100):r.qty*r.price*r.vat/100),0);const displayOptions=getDisplayOptions();const payload={company_id:currentCompanyId,document_scope:currentMembership?.role==='service'?'service':(offerMode?currentOffer?.payload?.document_scope:window._approvalRow?.document_scope)||'sales',vat_mode:vatMode,display_options:displayOptions,proforma_number:val('no'),proforma_date:val('date'),customer_name:val('buyerName')||'Müşteri',customer_snapshot:customer,currency:val('currency'),exchange_rate:+val('rate')||null,payment_terms:val('payment'),bidder:val('bidder'),subtotal,vat_total,grand_total:subtotal+vat_total,items:rows,bank_accounts:getBanks(),notes:val('notes'),validity_days:+val('validityDays')||7,valid_until:calcValidUntil(),rate_source:window._rateSource||'Manuel',rate_fetched_at:window._rateFetchedAt||null,status_changed_at:(window._loadedStatus&&window._loadedStatus===val('status'))?(window._loadedStatusChangedAt||null):new Date().toISOString()};return payload;}
let offerMode=false,currentOffer=null,offerRows=[],offerBusy=false;
function offerAllowed(){return !!currentUser&&['owner','admin','manager','sales','service'].includes(currentMembership?.role)}
const offerStatus={draft:'Teklif hazır',accepted:'Müşteri kabul etti',converted:'Proformaya dönüştürüldü'};
async function offerRpc(action,body={},note='',id=currentOffer?.id,revision=currentOffer?.revision||1){const {data,error}=await sb.rpc('sales_offer_action',{p_company_id:currentCompanyId,p_id:id||null,p_revision:revision,p_action:action,p_body:body,p_note:note});if(error)throw error;return data}
async function openOffers(){if(!offerAllowed()){alert('Teklif yetkiniz yok.');return}closeAllProeraViews();offerMode=false;document.getElementById('offersOverlay').hidden=false;await loadOffers()}
async function loadOffers(){const company=currentCompanyId;const box=document.getElementById('offersList');box.textContent='Teklifler yükleniyor…';const {data,error}=await sb.from('sales_offers').select('*').eq('company_id',company).order('created_at',{ascending:false}).limit(200);if(company!==currentCompanyId||!offerAllowed())return;if(error){box.textContent=error.message;return}offerRows=data||[];const search=val('offersSearch').toLocaleLowerCase('tr-TR');box.innerHTML=offerRows.filter(o=>(o.offer_number+' '+o.payload.customer_name).toLocaleLowerCase('tr-TR').includes(search)).map(o=>`<article class="offer-card"><div><b>${esc(o.offer_number)}</b><h3>${esc(o.payload.customer_name)}</h3><p>${money(Number(o.payload.grand_total)||0)} ${esc(o.payload.currency||'')} · ${esc(offerStatus[o.status])}</p><small>${esc(o.payload.bidder||'')} · Sürüm ${o.revision}${o.parent_offer_id?' · Önceki teklif #'+o.parent_offer_id:''}${o.accepted_at?' · Kabul: '+esc(auditTime(o.accepted_at)):''}${o.acceptance_note?' · '+esc(o.acceptance_note):''}</small></div><div class="actions"><button class="btn light" data-offer-open="${o.id}">Aç / PDF</button><button class="btn light" data-offer-wa="${o.id}">WhatsApp</button>${o.status==='draft'?`<button class="btn primary" data-offer-accept="${o.id}">Müşteri kabulünü kaydet</button>`:`<button class="btn primary" data-offer-convert="${o.id}">${o.status==='converted'?'Proformayı aç':'Proformaya dönüştür'}</button><button class="btn light" data-offer-revise="${o.id}">Yeni revizyon</button>`}</div></article>`).join('')||'<p>Teklif bulunamadı.</p>';for(const [attr,fn] of [['open',openOffer],['wa',shareOffer],['accept',acceptOffer],['convert',convertOffer],['revise',reviseOffer]])box.querySelectorAll('[data-offer-'+attr+']').forEach(b=>b.onclick=()=>fn(Number(b.getAttribute('data-offer-'+attr))))}
async function getOffer(id){const {data,error}=await sb.from('sales_offers').select('*').eq('company_id',currentCompanyId).eq('id',id).single();if(error)throw error;return data}
async function newOffer(){if(!offerAllowed())return;closeAllProeraViews();await startNewProforma();offerMode=true;currentOffer=null;window._openedArchiveId=null;window._approvalRow=null;document.getElementById('no').value='Kayıtta oluşturulur';render();uiQuotePreview(false)}
async function openOffer(id){try{const o=await getOffer(id);if(!offerAllowed())return;closeAllProeraViews();offerMode=true;currentOffer=o;window._openedArchiveId=null;window._approvalRow=null;document.body.classList.remove('view-mode');fillOfferEditor(o.payload);render();uiQuotePreview(false)}catch(e){alert('Teklif açılamadı: '+e.message)}}
async function saveOffer(print=false){if(offerBusy||!offerAllowed())return;if(currentOffer&&currentOffer.status!=='draft'){if(print){fillOfferEditor(currentOffer.payload);render();document.title=currentOffer.offer_number+' - '+safeFileName(val('buyerName'));window.print();return true}alert('Kabul edilen teklif korunur. Yeni revizyon oluşturabilirsiniz.');return}if(!validateProforma()||!val('bidder').trim()){alert('Müşteri, ürün ve satış sorumlusunu doldurun.');return}offerBusy=true;try{const body=buildOfferPayload();currentOffer=await offerRpc('save',body);document.getElementById('no').value=currentOffer.offer_number;render();if(print){document.title=currentOffer.offer_number+' - '+safeFileName(val('buyerName'));window.print()}return true}catch(e){alert('Teklif kaydedilemedi: '+e.message)}finally{offerBusy=false}}
async function acceptOffer(id){const note=prompt('Müşterinin kabul açıklaması (ör. WhatsApp ile kabul etti):');if(!note)return;try{const o=await getOffer(id);await offerRpc('accept',{},note,o.id,o.revision);await loadOffers()}catch(e){alert(e.message)}}
async function convertOffer(id){if(offerBusy)return;offerBusy=true;try{const o=await getOffer(id),r=await offerRpc('convert',{},'',o.id,o.revision);offerMode=false;currentOffer=null;closeAllProeraViews();await loadSavedProforma(r.proforma_id);uiQuotePreview(false);render();alert('Proforma hazır. Yönetici onayına gönderebilirsiniz.')}catch(e){alert(e.message)}finally{offerBusy=false}}
