function whatsappUrl(phone,message){let p=String(phone||'').replace(/\D/g,'');if(p.startsWith('00'))p=p.slice(2);if(p.length===11&&p.startsWith('0'))p='90'+p.slice(1);if(p.length===10)p='90'+p;if(p.length<10||p.length>15)throw Error('Müşteri telefonunu ülke koduyla doldurun.');return 'https://wa.me/'+p+'?text='+encodeURIComponent(message)}
async function shareOffer(id){const tab=window.open('about:blank','_blank');try{const o=await getOffer(id);const url=whatsappUrl(o.payload.customer_snapshot?.phone,`Merhaba ${o.payload.customer_name}, ${o.offer_number} numaralı fiyat teklifimizi değerlendirmenize sunuyoruz. Teklif PDF’sini bu görüşmeye ayrıca ekleyeceğim.`);await offerRpc('share',{},'',o.id,o.revision);if(tab){tab.opener=null;tab.location=url}else alert('WhatsApp penceresi engellendi. Açılır pencerelere izin verin.');}catch(e){tab?.close();alert(e.message)}}
async function shareCurrentOffer(){if(currentOffer?.status!=='draft'&&currentOffer?.id)return shareOffer(currentOffer.id);if(await saveOffer(false))return shareOffer(currentOffer.id)}
async function shareProformaWhatsApp(id){const tab=window.open('about:blank','_blank');try{const {data,error}=await sb.rpc('request_proforma_whatsapp',{p_id:id});if(error)throw error;const url=whatsappUrl(data.phone,`Merhaba ${data.customer}, yönetici onaylı ${data.number} numaralı proformamızı paylaşıyoruz. Kaşe ve imzalı PDF’yi bu görüşmeye ayrıca ekleyeceğim.`);if(tab){tab.opener=null;tab.location=url}else alert('WhatsApp penceresi engellendi.');}catch(e){tab?.close();alert(e.message)}}
