let tlConversionBusy=false;
function readItemConversion(item){try{return item.dataset.fx?JSON.parse(item.dataset.fx):null}catch{return null}}
async function euroRateForConversion(){const {data,error}=await sb.functions.invoke('currency-rate',{body:{currency:'EUR'}});const age=Date.now()-Date.parse(data?.as_of);if(error||data?.currency!=='EUR'||!(Number(data.rate)>0)||!Number.isFinite(age)||age>7*86400000)throw Error('Euro kuru alınamadı. Fiyatlar değiştirilmedi.');return data}
function markItemConversion(item,fx){item.dataset.fx=JSON.stringify(fx);item.querySelector('.price').value=formatTrInput(Math.round(fx.source_price*fx.rate*100)/100)}
async function convertDocumentToTL(){if(tlConversionBusy)return;const old=val('currency'),rows=[...document.querySelectorAll('.item')].filter(x=>x.querySelector('.desc').value.trim());if(currentOffer&&currentOffer.status!=='draft'&&offerMode){alert('Kabul edilen teklif korunur. Önce yeni revizyon oluşturun.');return false}if(!['€','EUR','TL'].includes(old)){alert('Bu seçenek Euro fiyatlarını TL’ye çevirir.');return false}if(old==='TL'&&rows.some(x=>!readItemConversion(x))){alert('TL satırların Euro karşılığı bilinmiyor. Euro ürünlerini katalogdan ekleyin.');return false}tlConversionBusy=true;document.getElementById('tlConversionStatus').textContent='Euro kuru alınıyor…';try{const d=await euroRateForConversion();if(rows.some(x=>!x.isConnected)||old!==val('currency'))throw Error('Para birimi değişti; yeniden deneyin.');for(const item of rows){const saved=readItemConversion(item),price=saved?.source_price??parseTrNumber(item.querySelector('.price').value);markItemConversion(item,{source_currency:'EUR',source_price:price,rate:Number(d.rate),source:d.source,as_of:d.as_of,converted_at:new Date().toISOString()})}document.getElementById('currency').value='TL';document.getElementById('rate').value='1';window._rateCurrency='TL';window._rateFetchedAt=d.as_of;window._rateSource=d.source+' · EUR→TL';window._rateRequest=(window._rateRequest||0)+1;render();saveDraftDebounced();return true}catch(e){document.getElementById('tlConversionStatus').textContent=e.message;alert(e.message);return false}finally{tlConversionBusy=false}}
async function tlCatalogueProduct(p,item=null){if(currentMembership?.role==='service'&&!p.is_service_part){alert('Yalnızca servis parçaları eklenebilir.');return false}if((p.currency||'EUR')!=='EUR'&&(p.currency||'EUR')!=='TRY'){alert('TL belgeye bu seçenekle yalnızca Euro veya TL ürün ekleyebilirsiniz.');return false}let fx=null;if((p.currency||'EUR')==='EUR'){const d=await euroRateForConversion();fx={source_currency:'EUR',source_price:Number(p.default_price)||0,rate:Number(d.rate),source:d.source,as_of:d.as_of,converted_at:new Date().toISOString()}}if(val('currency')!=='TL')throw Error('Para birimi değişti; ürünü yeniden seçin.');if(!item){document.querySelectorAll('.item').forEach(x=>{if(!x.querySelector('.desc').value.trim()&&!parseTrNumber(x.querySelector('.price').value))x.remove()});addItem({product_id:p.id,desc:p.name,product_code:p.product_code,gtip:p.gtip,brand:p.brand,origin:p.origin,model:p.model,qty:1,price:fx?Math.round(fx.source_price*fx.rate*100)/100:p.default_price,vat:p.vat_rate,currency_conversion:fx});}else{item.dataset.productId=p.id;item.dataset.productCode=p.product_code||'';for(const [selector,key] of [['.desc','name'],['.gtip','gtip'],['.pbrand','brand'],['.porigin','origin'],['.pmodel','model']])item.querySelector(selector).value=p[key]||'';item.querySelector('.vat').value=p.vat_rate??20;item.querySelector('.price').value=formatTrInput(p.default_price??0);delete item.dataset.fx;if(fx)markItemConversion(item,fx);item.querySelector('.product-results').style.display='none'}render();saveDraftDebounced();return true}
const tlOneBase=addOneCatalogProduct;addOneCatalogProduct=async function(id){if(val('currency')!=='TL')return tlOneBase(id);try{const p=(window._catalog||[]).find(x=>String(x.id)===String(id));if(p&&await tlCatalogueProduct(p))closeCatalog()}catch(e){alert(e.message)}};
const tlSelectedBase=addSelectedCatalogProducts;addSelectedCatalogProducts=async function(){if(val('currency')!=='TL')return tlSelectedBase();const ids=[...document.querySelectorAll('.catalog-pick:checked')].map(x=>x.value);if(!ids.length){alert('Ürün seçin.');return}try{for(const id of ids){const p=(window._catalog||[]).find(x=>String(x.id)===id);if(p)await tlCatalogueProduct(p)}closeCatalog()}catch(e){alert(e.message)}};
const tlApplyBase=applyProductToItem;applyProductToItem=async function(item,p){if(val('currency')!=='TL'){delete item.dataset.fx;return tlApplyBase(item,p)}try{await tlCatalogueProduct(p,item)}catch(e){alert(e.message)}};
const tlAddBase=addItem;addItem=function(data={}){tlAddBase(data);const item=document.querySelector('#items .item:last-child');if(data.currency_conversion&&item){item.dataset.fx=JSON.stringify(data.currency_conversion);render()}};
(function(){const box=document.createElement('div');box.id='tlConversionTools';box.className='approval-tools';box.innerHTML='<button type="button" class="btn light" onclick="convertDocumentToTL()">Euro fiyatlarını güncel kurla TL’ye çevir</button><p id="tlConversionStatus" class="muted">TL seçiliyken katalogdaki Euro ürünleri otomatik çevrilir. Katalog fiyatı değişmez.</p>';document.getElementById('rateStatus').after(box);document.getElementById('currency').addEventListener('change',async e=>{const cur=val('currency'),rows=[...document.querySelectorAll('.item')].filter(x=>x.querySelector('.desc').value.trim());if(cur==='TL'&&rows.length&&!rows.every(x=>readItemConversion(x))){e.stopImmediatePropagation();document.getElementById('currency').value=window._rateCurrency||'€';await convertDocumentToTL()}else if(cur!=='TL'&&rows.some(x=>readItemConversion(x))){e.stopImmediatePropagation();document.getElementById('currency').value='TL';if(cur!=='€'){alert('TL’ye çevrilmiş satırlar için önce Euro’ya dönün.');return}if(!confirm('Fiyatlar dönüşümden önceki Euro değerlerine geri alınsın mı?'))return;for(const item of rows){const fx=readItemConversion(item);if(!fx){alert('TL ürün içeren belge Euro’ya otomatik çevrilemez.');return}}for(const item of rows){item.querySelector('.price').value=formatTrInput(readItemConversion(item).source_price);delete item.dataset.fx}document.getElementById('currency').value='€';await fetchRate();render()}},true)})();
const tlRenderBase=render;render=function(){tlRenderBase();const fx=[...document.querySelectorAll('.item')].map(readItemConversion).filter(Boolean);if(val('currency')==='TL'&&fx.length){const rates=[...new Map(fx.map(x=>[x.rate+'|'+x.as_of,x])).values()];const text=rates.map(x=>'1 EUR = '+Number(x.rate).toLocaleString('tr-TR',{minimumFractionDigits:4,maximumFractionDigits:6})+' TL · '+x.source+' · '+auditTime(x.as_of)).join(' / ');document.getElementById('tlConversionStatus').textContent='Dönüşüm kuru: '+text;const node=document.querySelector('#paper .rate-box');if(node)node.textContent='Euro fiyatlarından TL’ye dönüşüm: '+text}else document.getElementById('tlConversionStatus').textContent='TL seçiliyken katalogdaki Euro ürünleri otomatik çevrilir. Katalog fiyatı değişmez.'};
