const opsOverlay=document.createElement('div');opsOverlay.id='ordersOverlay';opsOverlay.className='ops-overlay';opsOverlay.hidden=true;opsOverlay.innerHTML='<main class="ops-shell"><header class="ops-heading"><div><small class="workspace-kicker">PROERA · SİPARİŞ VE TESLİMAT</small><h1>Siparişler</h1><span class="ops-state">Onaylı proformadan faturaya, depo hazırlığından teslimata.</span></div><button class="btn light" id="opsClose">Kapat</button></header><div id="opsCounts" class="ops-stages"></div><div class="ops-filters"><input type="search" id="opsSearch" placeholder="Sipariş, proforma veya müşteri ara…" aria-label="Sipariş ara"><select id="opsFilter" aria-label="Sipariş durumu"><option value="active">Aktif siparişler</option><option value="finance">Fatura bekleyen</option><option value="warehouse">Paketleme bekleyen</option><option value="shipment">Sevkiyat bekleyen</option><option value="transit">Yolda / kısmi sevk</option><option value="partial">Kısmi sevkiyat</option><option value="delivered">Teslim edilen</option><option value="cancelled">İptal edilen</option><option value="all">Tümü</option></select><button class="btn light" id="opsRefresh">Yenile</button></div><p id="opsState" class="ops-state" role="status" aria-live="polite"></p><div id="opsList"></div><div class="ops-pagination"><button class="btn light" id="opsPrev">Önceki</button><span id="opsPage"></span><button class="btn light" id="opsNext">Sonraki</button></div></main>';document.body.append(opsOverlay);
const opsModal=document.createElement('div');opsModal.className='ops-modal';opsModal.hidden=true;opsModal.innerHTML='<section class="ops-dialog" role="dialog" aria-modal="true" aria-label="Sipariş işlemleri"><div class="ops-heading"><h2 id="opsModalTitle">Sipariş</h2><button class="btn light" id="opsModalClose">Kapat</button></div><p id="opsModalState" class="ops-state" role="status" aria-live="polite"></p><div id="opsModalBody"></div></section>';document.body.append(opsModal);
function opsKey(){return [currentCompanyId,currentUser?.id,currentMembership?.role].join('|')}
function clearOperations(){opsRequest++;opsDetail=null;opsTransfer=null;opsModal.hidden=true;opsOverlay.hidden=true;opsIdentity=opsKey();document.getElementById('opsList').replaceChildren();document.getElementById('opsModalBody').replaceChildren();document.getElementById('opsCounts').replaceChildren();document.getElementById('opsDashCounts')?.replaceChildren();const dash=document.getElementById('opsDashboard');if(dash)dash.hidden=true}
function closeOperationsModal(){if(opsBusy)return;opsRequest++;opsModal.hidden=true;opsDetail=null;opsTransfer=null;document.getElementById('opsModalBody').replaceChildren()}
document.getElementById('opsModalClose').onclick=closeOperationsModal;opsModal.onclick=e=>{if(e.target===opsModal)closeOperationsModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!opsModal.hidden)closeOperationsModal()});
const opsCloseBase=closeAllProeraViews;closeAllProeraViews=function(){opsCloseBase();clearOperations()};
const opsNavigateBase=appNavigate;appNavigate=async function(action){if(action==='orders'){if(!hasAppAction('orders'))return;document.querySelectorAll('.ds-nav button,.md-menu button').forEach(el=>{const active=(el.getAttribute('onclick')||'').includes("'orders'");el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});closeAllProeraViews();opsOverlay.hidden=false;opsPage=0;document.getElementById('opsSearch').value='';document.getElementById('opsFilter').value='active';return loadOperationOrders()}return opsNavigateBase(action)};
for(const nav of document.querySelectorAll('.ds-nav,.md-menu')){const b=document.createElement('button');b.className='ds-btn';b.type='button';b.setAttribute('onclick',"mobileNavigate('orders')");b.innerHTML='<span class="ds-icon">▣</span> Sipariş ve Teslimat';const service=[...nav.querySelectorAll('button')].find(x=>(x.getAttribute('onclick')||'').includes("Navigate('service')"));if(service)service.after(b);else nav.append(b);b.hidden=true}
const opsRoleBase=applyRoleNavigation;applyRoleNavigation=function(){opsRoleBase();if(opsIdentity!==opsKey())clearOperations();document.querySelectorAll('[onclick]').forEach(b=>{if((b.getAttribute('onclick')||'').includes("Navigate('orders')"))b.hidden=!hasAppAction('orders')});document.getElementById('opsClose').hidden=['accounting','logistics'].includes(currentMembership?.role)};
document.getElementById('opsClose').onclick=()=>appNavigate(roleLanding());document.getElementById('opsRefresh').onclick=()=>loadOperationOrders();document.getElementById('opsPrev').onclick=()=>{opsPage=Math.max(0,opsPage-1);loadOperationOrders()};document.getElementById('opsNext').onclick=()=>{opsPage++;loadOperationOrders()};let opsSearchTimer;document.getElementById('opsSearch').oninput=()=>{clearTimeout(opsSearchTimer);opsSearchTimer=setTimeout(()=>{opsPage=0;loadOperationOrders()},300)};document.getElementById('opsFilter').onchange=()=>{opsPage=0;loadOperationOrders()};
function orderReadAllowed(){return !!currentUser&&!!currentCompanyId&&hasAppAction('orders')}
function orderCanTransfer(){return ['owner','admin','manager','sales','service'].includes(currentMembership?.role)}
function opsCanEdit(section){const r=currentMembership?.role;return ['owner','admin'].includes(r)||(section==='finance'?r==='accounting':r==='logistics')}
function opsPill(section,state){return '<span class="ops-pill '+(['issued','packed','delivered'].includes(state)?'done':['preparing','allocated','planned','shipped'].includes(state)?'moving':'')+'">'+esc(opsLabels[section][state]||state)+'</span>'}
function opsMoney(value,currency){return Number(value||0).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+(currency||'')}
async function loadOperationOrders(){if(!orderReadAllowed())return;const token=++opsRequest,key=opsKey(),state=document.getElementById('opsState');state.textContent='Siparişler yükleniyor…';document.getElementById('opsList').replaceChildren();try{let q=sb.from('operation_orders').select('id,order_number,proforma_number,document_scope,customer_name,currency,grand_total,finance_status,warehouse_status,shipment_status,created_at,cancelled_at,revision',{count:'exact'}).eq('company_id',currentCompanyId);const filter=val('opsFilter'),search=val('opsSearch').trim();if(filter!=='all'){if(filter==='cancelled')q=q.not('cancelled_at','is',null);else q=q.is('cancelled_at',null)}if(filter==='active')q=q.neq('shipment_status','delivered');if(filter==='finance')q=q.neq('finance_status','issued');if(filter==='warehouse')q=q.neq('warehouse_status','packed').not('shipment_status','in','(shipped,delivered)');if(filter==='shipment')q=q.in('shipment_status',['waiting','planned','partial']);if(filter==='transit')q=q.in('shipment_status',['shipped','partial']);if(filter==='partial')q=q.eq('shipment_status','partial');if(filter==='delivered')q=q.eq('shipment_status','delivered');if(search){const safe=search.replace(/[%,()\\_"]/g,' ');q=q.or('customer_name.ilike.%'+safe+'%,order_number.ilike.%'+safe+'%,proforma_number.ilike.%'+safe+'%')}const {data,error,count}=await q.order('created_at',{ascending:false}).order('id',{ascending:false}).range(opsPage*25,opsPage*25+24);if(token!==opsRequest||key!==opsKey()||!orderReadAllowed())return;if(error)throw error;state.textContent=(count||0)+' sipariş · '+(teamRoles[currentMembership?.role]||'Şirket sahibi');document.getElementById('opsList').innerHTML=(data||[]).map(o=>'<article class="ops-card"><div><small>'+esc(o.order_number)+' · '+esc(o.proforma_number)+(o.document_scope==='service'?' · Servis parçaları':'')+'</small><h3>'+esc(o.customer_name)+'</h3><small>'+esc(auditTime(o.created_at))+'</small><div class="ops-pills">'+(o.cancelled_at?'<span class="ops-pill cancel">İptal edildi</span>':opsPill('finance',o.finance_status)+opsPill('warehouse',o.warehouse_status)+opsPill('shipment',o.shipment_status))+'</div></div><div><b>'+esc(opsMoney(o.grand_total,o.currency))+'</b><br><button class="btn light" data-ops-id="'+o.id+'">Siparişi aç →</button></div></article>').join('')||'<p class="ops-state">Bu filtreye uygun sipariş yok. Yönetici onaylı proformalar satış veya servis ekibi tarafından operasyona aktarılır.</p>';document.querySelectorAll('[data-ops-id]').forEach(b=>b.onclick=()=>openOperationOrder(Number(b.dataset.opsId)));document.getElementById('opsPrev').disabled=opsPage===0;document.getElementById('opsNext').disabled=(opsPage+1)*25>=(count||0);document.getElementById('opsPage').textContent='Sayfa '+(opsPage+1);await loadOperationsCounts('opsCounts')}catch(e){if(token===opsRequest)state.textContent='Siparişler yüklenemedi: '+e.message}}
async function loadOperationsCounts(target){if(!orderReadAllowed())return;const key=opsKey(),box=document.getElementById(target);if(!box)return;try{const rows=await Promise.all([['finance','finance_status','issued'],['warehouse','warehouse_status','packed'],['shipment','shipment_status','delivered']].map(async([kind,column,done])=>{const {count,error}=await sb.from('operation_orders').select('id',{count:'exact',head:true}).eq('company_id',currentCompanyId).is('cancelled_at',null).neq(column,done);if(error)throw error;return {kind,count}}));if(key!==opsKey()||!orderReadAllowed())return;box.innerHTML=rows.map(x=>'<div class="ops-stage"><small>'+({finance:'Muhasebe bekleyen',warehouse:'Depo bekleyen',shipment:'Teslimat bekleyen'})[x.kind]+'</small><b>'+x.count+'</b></div>').join('')}catch{if(key===opsKey())box.textContent='Bekleyen iş sayıları alınamadı.'}}
async function openOperationOrder(id){if(!orderReadAllowed())return;const token=++opsRequest,key=opsKey();opsModal.hidden=false;document.getElementById('opsModalTitle').textContent='Sipariş detayı';document.getElementById('opsModalBody').replaceChildren();document.getElementById('opsModalState').textContent='Yükleniyor…';try{const {data,error}=await sb.from('operation_orders').select('*').eq('company_id',currentCompanyId).eq('id',id).single();if(token!==opsRequest||key!==opsKey()||!orderReadAllowed())return;if(error)throw error;opsDetail=data;opsTransfer=null;document.getElementById('opsModalTitle').textContent=data.order_number+' · '+data.customer_name;document.getElementById('opsModalState').textContent=data.cancelled_at?'İptal edildi: '+data.cancel_reason:'Onaylı proforma ve fiyatlar kilitli · Son işlem: '+auditTime(data.updated_at);renderOperationDetail()}catch(e){if(token===opsRequest)document.getElementById('opsModalState').textContent=e.message}}
function opsInput(id,label,value,type='text'){return '<label>'+esc(label)+'<input id="'+id+'" type="'+type+'" value="'+esc(value||'')+'"></label>'}
function opsText(id,label,value){return '<label>'+esc(label)+'<textarea id="'+id+'">'+esc(value||'')+'</textarea></label>'}
function opsSelect(id,label,values,value){return '<label>'+esc(label)+'<select id="'+id+'">'+Object.entries(values).map(([k,v])=>'<option value="'+k+'" '+(value===k?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>'}
function renderOperationDetail(){const o=opsDetail;if(!o)return;const finance=opsCanEdit('finance')&&!o.cancelled_at&&!['shipped','delivered'].includes(o.shipment_status),warehouse=opsCanEdit('warehouse')&&!o.cancelled_at&&!['shipped','delivered'].includes(o.shipment_status),shipment=opsCanEdit('shipment')&&!o.cancelled_at&&o.shipment_status!=='delivered';const p=o.proforma_snapshot||{},buyer=p.customer_snapshot||{};const img=src=>typeof src==='string'&&/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(src)?'<img class="ops-stamp" src="'+src+'" alt="Onayda kullanılan kaşe / imza">':'';
document.getElementById('opsModalBody').innerHTML='<div class="ops-detail-grid"><section class="ops-box ops-full"><h3>Onaylı proforma · '+esc(o.proforma_number)+'</h3><p><b>'+esc(o.customer_name)+'</b> · '+esc(buyer.tax_office||'')+' / '+esc(buyer.tax_number||'')+'<br>'+esc(buyer.address||'')+'</p><div class="ops-products"><table><thead><tr><th>Ürün</th><th>Adet</th><th>Birim fiyat</th><th>KDV</th></tr></thead><tbody>'+(p.items||[]).map(i=>'<tr><td><b>'+esc(i.description||i.desc||'Ürün')+'</b><br><small>'+esc([i.brand,i.model,i.serial].filter(Boolean).join(' · '))+'</small></td><td>'+esc(i.qty)+'</td><td>'+esc(opsMoney(i.price,p.currency))+'</td><td>%'+esc(i.vat)+'</td></tr>').join('')+'</tbody></table></div><p>Ara toplam: '+esc(opsMoney(p.subtotal,p.currency))+' · KDV: '+esc(opsMoney(p.vat_total,p.currency))+'<br><b>Genel toplam: '+esc(opsMoney(p.grand_total,p.currency))+'</b><br>Fiyatlar KDV '+(p.vat_mode==='included'?'dahil':'hariç')+' · Ödeme şartları: '+esc(p.payment_terms||'Belirtilmedi')+'</p><details><summary>Yönetici onayı ve ek bilgiler</summary><p>Onay: '+esc(auditTime(p.approved_at))+' · Proforma sürümü: '+esc(o.proforma_revision)+'</p>'+img(p.approved_stamp_data)+img(p.approved_signature_data)+'<p>'+esc(p.notes||'')+'</p></details></section><section class="ops-box ops-full"><h3>Teslimat bilgileri</h3><p>'+esc(o.delivery_address)+'<br>'+esc(o.delivery_contact)+' · '+esc(o.delivery_phone)+'</p><p>Satış notu: '+esc(o.sales_note||'—')+'</p><small>Müşteri teyidi kaydı: '+esc(auditTime(o.customer_confirmed_at))+'</small></section><section class="ops-box"><h3>Muhasebe</h3><fieldset '+(finance?'':'disabled')+'>'+opsSelect('opsFinanceStatus','Fatura durumu',opsLabels.finance,o.finance_status)+'<div class="grid">'+opsInput('opsInvoiceNo','Fatura numarası',o.invoice_number)+opsInput('opsInvoiceDate','Fatura tarihi',o.invoice_date,'date')+'</div>'+opsText('opsFinanceNote','Muhasebe notu',o.finance_note)+(finance?'<button class="btn primary" data-ops-save="finance">Muhasebe bilgilerini kaydet</button>':'')+'</fieldset><p class="ops-state">Faturayı mevcut muhasebe sisteminizde düzenleyip bilgilerini buraya kaydedin.</p></section><section class="ops-box"><h3>Depo hazırlığı</h3><fieldset '+(warehouse?'':'disabled')+'>'+opsSelect('opsWarehouseStatus','Hazırlık durumu',opsLabels.warehouse,o.warehouse_status)+opsText('opsSerials','Ürün / seri numaraları',o.serial_numbers)+opsText('opsWarehouseNote','Depo notu',o.warehouse_note)+(warehouse?'<button class="btn primary" data-ops-save="warehouse">Depo bilgilerini kaydet</button>':'')+'</fieldset><p class="ops-state">Bu hazırlık kaydı stok miktarını değiştirmez.</p></section><section class="ops-box ops-full"><h3>Sevkiyat ve teslim</h3><fieldset '+(shipment?'':'disabled')+'><div class="grid">'+opsSelect('opsShipmentStatus','Sevkiyat durumu',opsLabels.shipment,o.shipment_status)+opsSelect('opsMethod','Sevkiyat yöntemi',{'':'Seçiniz',...opsLabels.method},o.shipment_method)+opsInput('opsPlannedDate','Planlanan tarih',o.planned_date,'date')+opsInput('opsShippedDate','Çıkış tarihi',o.shipped_date,'date')+'</div><div class="grid" id="opsCargoFields">'+opsInput('opsCargoCompany','Kargo firması',o.cargo_company)+opsInput('opsTrackingNo','Takip numarası',o.tracking_number)+'</div><div class="grid" id="opsVehicleFields">'+opsInput('opsPlate','Araç plakası',o.vehicle_plate)+opsInput('opsDeliveryPerson','Teslimat sorumlusu / teslim alacak kişi',o.delivery_person)+'</div><div class="grid">'+opsInput('opsDispatchNo','İrsaliye numarası',o.dispatch_number)+opsInput('opsDispatchDate','İrsaliye tarihi',o.dispatch_date,'date')+opsInput('opsDeliveredDate','Teslim tarihi',o.delivered_date,'date')+opsInput('opsReceivedBy','Teslim alan kişi',o.received_by)+'</div>'+opsText('opsShipmentNote','Sevkiyat notu',o.shipment_note)+(shipment?'<button class="btn primary" data-ops-save="shipment">Sevkiyat bilgilerini kaydet</button>':'')+'</fieldset><p class="ops-state">İrsaliyeyi mevcut sisteminizde düzenleyip bilgilerini kaydedin. Çıkış için fatura ve paketleme tamamlanmalı.</p></section></div>'+(!o.cancelled_at&&['owner','admin'].includes(currentMembership?.role)&&o.finance_status!=='issued'&&!['shipped','delivered'].includes(o.shipment_status)?'<div class="actions"><button class="btn danger" id="opsCancelOrder">Siparişi iptal et</button></div>':'');document.getElementById('opsMethod').onchange=updateShipmentFields;updateShipmentFields();document.querySelectorAll('[data-ops-save]').forEach(b=>b.onclick=()=>saveOperationSection(b.dataset.opsSave));const cancel=document.getElementById('opsCancelOrder');if(cancel)cancel.onclick=()=>saveOperationSection('cancel')}
function updateShipmentFields(){const m=val('opsMethod');document.getElementById('opsCargoFields').hidden=m!=='cargo';document.getElementById('opsVehicleFields').hidden=!['vehicle','pickup'].includes(m);document.getElementById('opsPlate').closest('label').hidden=m!=='vehicle'}
async function saveOperationSection(section){if(opsBusy||!opsDetail||!orderReadAllowed())return;let data;if(section==='finance')data={status:val('opsFinanceStatus'),number:val('opsInvoiceNo'),date:val('opsInvoiceDate'),note:val('opsFinanceNote')};else if(section==='warehouse')data={status:val('opsWarehouseStatus'),serials:val('opsSerials'),note:val('opsWarehouseNote')};else if(section==='shipment')data={status:val('opsShipmentStatus'),method:val('opsMethod'),planned_date:val('opsPlannedDate'),shipped_date:val('opsShippedDate'),delivered_date:val('opsDeliveredDate'),received_by:val('opsReceivedBy'),dispatch_number:val('opsDispatchNo'),dispatch_date:val('opsDispatchDate'),cargo_company:val('opsCargoCompany'),tracking_number:val('opsTrackingNo'),vehicle_plate:val('opsPlate'),delivery_person:val('opsDeliveryPerson'),note:val('opsShipmentNote')};else{const reason=prompt('Siparişi iptal etme gerekçesi (en az 5 karakter):');if(reason===null)return;data={reason}}const key=opsKey(),id=opsDetail.id,revision=opsDetail.revision;opsBusy=true;document.querySelectorAll('[data-ops-save],#opsCancelOrder').forEach(b=>b.disabled=true);const state=document.getElementById('opsModalState');state.textContent='Kaydediliyor…';try{const {error}=await sb.rpc('update_operation_order',{p_company_id:currentCompanyId,p_id:id,p_revision:revision,p_action:section,p_data:data});if(key!==opsKey()||!currentUser)return;if(error)throw error;await openOperationOrder(id);if(!opsOverlay.hidden)await loadOperationOrders();await loadOperationsCounts('opsDashCounts')}catch(e){if(key===opsKey())state.textContent='Kaydedilemedi: '+e.message}finally{opsBusy=false;document.querySelectorAll('[data-ops-save],#opsCancelOrder').forEach(b=>b.disabled=false)}}
async function beginOrderTransfer(id,revision){if(!orderCanTransfer()||!currentUser)return;const token=++opsRequest,key=opsKey();opsModal.hidden=false;document.getElementById('opsModalTitle').textContent='Siparişi operasyona aktar';document.getElementById('opsModalState').textContent='Proforma kontrol ediliyor…';document.getElementById('opsModalBody').replaceChildren();try{const {data:p,error}=await sb.from('proformas').select('*').eq('company_id',currentCompanyId).eq('id',id).single();if(token!==opsRequest||key!==opsKey())return;if(error)throw error;if(p.approval_state!=='approved'||Number(p.approval_revision)!==Number(revision))throw Error('Güncel yönetici onaylı proforma gerekli.');opsDetail=null;opsTransfer=p;const c=p.customer_snapshot||{};document.getElementById('opsModalState').textContent=p.proforma_number+' · '+p.customer_name+' · '+opsMoney(p.grand_total,p.currency);document.getElementById('opsModalBody').innerHTML='<section class="ops-box"><p>Aktarımdan sonra proforma fiyatları ve ürünleri kilitlenir. Muhasebe ve depo bu sipariş üzerinden çalışır.</p>'+opsText('opsTransferAddress','Teslimat adresi *',c.address)+opsInput('opsTransferContact','Teslimatta ilgili kişi *',c.name||p.customer_name)+opsInput('opsTransferPhone','Telefon *',c.phone)+opsText('opsTransferNote','Satış / teslimat notu','')+'<label class="ops-confirm"><input id="opsCustomerConfirmed" type="checkbox"><span>Müşteri proformayı teyit etti; teslimat bilgilerini kontrol ettim.</span></label><button class="btn primary" id="opsTransferSave">Muhasebe ve depoya aktar</button></section>';document.getElementById('opsTransferSave').onclick=confirmOrderTransfer}catch(e){if(token===opsRequest)document.getElementById('opsModalState').textContent=e.message}}
async function confirmOrderTransfer(){if(opsBusy||!opsTransfer||!orderCanTransfer())return;const state=document.getElementById('opsModalState');if(!document.getElementById('opsCustomerConfirmed').checked){state.textContent='Müşteri teyidini ve teslimat bilgilerini kontrol ettiğinizi işaretleyin.';return}const key=opsKey(),p=opsTransfer;opsBusy=true;document.getElementById('opsTransferSave').disabled=true;try{const {data,error}=await sb.rpc('transfer_proforma_order',{p_company_id:currentCompanyId,p_proforma_id:p.id,p_revision:p.approval_revision,p_address:val('opsTransferAddress'),p_contact:val('opsTransferContact'),p_phone:val('opsTransferPhone'),p_note:val('opsTransferNote')});if(key!==opsKey()||!currentUser)return;if(error)throw error;opsBusy=false;await appNavigate('orders');await openOperationOrder(Number(data))}catch(e){if(key===opsKey()){state.textContent='Aktarılamadı: '+e.message;document.getElementById('opsTransferSave').disabled=false}}finally{opsBusy=false}}
const opsApprovalBase=approvalActions;approvalActions=function(p){return opsApprovalBase(p)+(p.approval_state==='approved'&&orderCanTransfer()?'<div class="actions"><button class="btn primary" onclick="event.stopPropagation();beginOrderTransfer('+Number(p.id)+','+Number(p.approval_revision)+')">Siparişi operasyona aktar</button></div>':'')};
const opsDash=document.createElement('section');opsDash.className='ops-dash';opsDash.id='opsDashboard';opsDash.innerHTML='<h3>Muhasebe, depo ve teslimat takibi</h3><div id="opsDashCounts" class="ops-stages"></div><button class="btn light" onclick="appNavigate(\'orders\')">Siparişleri aç →</button>';document.querySelector('.dash-main-grid')?.before(opsDash);opsDash.hidden=true;const opsDashboardBase=loadDashboard;loadDashboard=async function(){await opsDashboardBase();opsDash.hidden=!orderReadAllowed();if(!opsDash.hidden)await loadOperationsCounts('opsDashCounts')};
Object.assign(auditTableLabels,{operation_orders:'Sipariş ve Teslimat'});document.getElementById('auditModule').append(new Option('Sipariş ve Teslimat','operation_orders'));Object.assign(auditFieldLabels,{order_number:'Sipariş numarası',proforma_revision:'Aktarılan proforma sürümü',proforma_snapshot:'Onaylı proforma kopyası',delivery_address:'Teslimat adresi',delivery_contact:'Teslimatta ilgili kişi',delivery_phone:'Teslimat telefonu',customer_confirmed_at:'Müşteri teyidinin kayıt zamanı',finance_status:'Muhasebe durumu',invoice_number:'Fatura numarası',invoice_date:'Fatura tarihi',warehouse_status:'Depo durumu',serial_numbers:'Ürün / seri numaraları',shipment_status:'Sevkiyat durumu',shipment_method:'Sevkiyat yöntemi',dispatch_number:'İrsaliye numarası',dispatch_date:'İrsaliye tarihi',tracking_number:'Kargo takip numarası',vehicle_plate:'Araç plakası',cancelled_at:'İptal zamanı',cancel_reason:'İptal gerekçesi'});
Object.assign(auditEventLabels,{order_transferred:'Sipariş operasyona aktarıldı',order_cancelled:'Sipariş iptal edildi',order_finance_updated:'Muhasebe bilgileri güncellendi',order_warehouse_updated:'Depo hazırlığı güncellendi',order_shipment_updated:'Sevkiyat / teslimat güncellendi'});for(const [v,t] of Object.entries(auditEventLabels)){if(!document.querySelector('#auditEvent option[value="'+v+'"]'))document.getElementById('auditEvent').append(new Option(t,v))}
