let p2Data=null,p2Promise=Promise.resolve(),p2Epoch=0,p2Draft=null;
const p2Today=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const p2Editable=()=>!!opsDetail&&!opsDetail.cancelled_at&&opsCanEdit('warehouse');
