renderOperationDetail=function(){
 p2RenderBase();p2Data=null;p2Draft=null;const epoch=++p2Epoch;
 const grid=document.querySelector('#opsModalBody .ops-detail-grid');if(!grid)return;
 [...grid.children].find(x=>x.querySelector('h3')?.textContent==='Sevkiyat ve teslim')?.remove();
 if(opsDetail.shipment_status==='partial'){document.getElementById('opsFinanceStatus')?.closest('fieldset')?.setAttribute('disabled','');document.querySelector('[data-ops-save="finance"]')?.remove();document.getElementById('opsCancelOrder')?.remove()}
 const stockHint=[...grid.querySelectorAll('p.ops-state')].find(x=>x.textContent.includes('hazırlık kaydı'));if(stockHint)stockHint.textContent='Rezervasyon ürünü bu siparişe ayırır. Fiziksel stok yalnızca sevkiyat çıkışında azalır.';
 grid.insertAdjacentHTML('beforeend','<section class="ops-box ops-full" id="p2Stock"><h3>Ürün rezervasyonu</h3><p>Yükleniyor…</p></section><section class="ops-box ops-full" id="p2Shipments"><h3>Sevkiyatlar</h3><p>Yükleniyor…</p></section>');
 p2Promise=p2Load(epoch,opsKey(),opsDetail.id);
};
const p2OpenBase=openOperationOrder;openOperationOrder=async function(id){await p2OpenBase(id);await p2Promise};
async function p2Load(epoch,key,id){
 try{
 const queries=['operation_order_lines','operation_shipments','operation_documents'].map(t=>sb.from(t).select('*').eq('company_id',currentCompanyId).eq('order_id',id).order('id'));
 const results=await Promise.all(queries);for(const r of results)if(r.error)throw r.error;
 const [lines,ships,docs]=results.map(r=>r.data||[]);
 const [sl,inv]=await Promise.all([ships.length?sb.from('operation_shipment_lines').select('*').eq('company_id',currentCompanyId).in('shipment_id',ships.map(s=>s.id)):Promise.resolve({data:[]}),opsCanEdit('warehouse')?sb.rpc('operation_inventory',{p_company_id:currentCompanyId}):Promise.resolve({data:[]})]);
 if(sl.error)throw sl.error;if(inv.error)throw inv.error;
 if(epoch!==p2Epoch||key!==opsKey()||opsDetail?.id!==id||opsModal.hidden)return;
 p2Data={lines,ships,docs,items:sl.data||[],inventory:inv.data||[]};p2Draw();
 }catch(e){if(epoch===p2Epoch&&key===opsKey()){document.getElementById('p2Stock').textContent='Stok bilgileri alınamadı: '+e.message;document.getElementById('p2Shipments').innerHTML='<button class="btn light" id="p2Retry">Tekrar yükle</button>';document.getElementById('p2Retry').onclick=()=>openOperationOrder(id)}}
}
function p2Planned(id){return p2Data.items.filter(i=>i.order_line_id===id&&p2Data.ships.some(s=>s.id===i.shipment_id&&s.status==='planned')).reduce((n,i)=>n+i.quantity,0)}
function p2Capacity(l){return Math.max(0,(l.stock_required?l.reserved_qty:l.quantity-l.shipped_qty)-p2Planned(l.id))}
function p2Files(kind,sid){
 const files=p2Data.docs.filter(d=>d.state==='ready'&&d.kind===kind&&(d.shipment_id||null)===(sid||null)).sort((a,b)=>b.created_at.localeCompare(a.created_at));
 const can=!opsDetail.cancelled_at&&opsCanEdit(kind==='invoice'?'finance':'warehouse')&&(!sid||p2Data.ships.find(s=>s.id===sid)?.status!=='cancelled');
 return '<div class="p2-documents"><h4>'+(kind==='invoice'?'Fatura PDF’leri':'İrsaliye PDF’leri')+'</h4><p class="ops-state">Önceki dosyalar korunur. PDF, en fazla 10 MB.</p>'+files.map((d,i)=>'<p><button class="btn light" data-p2-download="'+d.id+'">'+esc(d.file_name)+'</button> <small>'+esc(auditTime(d.ready_at))+(i===0?' · Son sürüm':' · Önceki sürüm')+'</small></p>').join('')+(files.length?'':'<p class="ops-state">Henüz belge eklenmedi.</p>')+(can?'<label>PDF ekle<input type="file" accept=".pdf,application/pdf" data-p2-upload="'+kind+'" data-shipment="'+(sid||'')+'"></label>':'')+'</div>';
}
function p2Draw(){
 if(!p2Data||!opsDetail)return;const edit=p2Editable()&&!['shipped','delivered'].includes(opsDetail.shipment_status);
 document.getElementById('p2Stock').innerHTML='<h3>Ürün ve stok rezervasyonu</h3><p class="ops-state">Ayrılan miktar bu siparişe aittir. Kalan = sipariş − gönderilen. Diğer siparişlerin rezervasyonları kullanılamaz.</p><div class="ops-products"><table><thead><tr><th>Ürün / katalog eşleştirmesi</th><th>Sipariş</th><th>Ayrılan</th><th>Gönderilen</th><th>Kalan</th></tr></thead><tbody>'+p2Data.lines.map(l=>{
 const inv=p2Data.inventory.find(p=>p.id===l.product_id);const locked=l.shipped_qty>0||p2Planned(l.id)>0;
 const opts=p2Data.inventory.filter(p=>opsDetail.document_scope!=='service'||p.is_service_part).map(p=>'<option value="'+p.id+'" '+(p.id===l.product_id?'selected':'')+'>'+esc(p.name)+' · Kullanılabilir '+p.available_qty+'</option>').join('');
 return '<tr data-p2-line="'+l.id+'"><td><b>'+esc(l.description)+'</b>'+(edit?'<label>Katalog ürünü<select data-product '+(locked?'disabled':'')+'><option value="">Ürün seçiniz</option>'+opts+'</select></label>':'')+(inv?'<small>Fiziksel: '+inv.stock_quantity+' · Tüm rezervasyonlar: '+inv.reserved_qty+' · Kullanılabilir: '+inv.available_qty+'</small>':'<small>'+(l.stock_required?'Katalog eşleştirmesini kontrol edin.':'Stok dışı hizmet / masraf')+'</small>')+(edit&&['owner','admin'].includes(currentMembership?.role)&&opsDetail.document_scope!=='service'?'<label><input style="width:auto" type="checkbox" data-nonstock '+(!l.stock_required?'checked':'')+' '+(locked?'disabled':'')+'> Stok dışı hizmet / masraf</label>':'')+(edit?'<input data-mapping-note aria-label="Eşleştirme açıklaması" placeholder="Stok dışı ise gerekçe (en az 5 karakter)" maxlength="500" value="'+esc(l.mapping_note||'')+'">':'')+'</td><td>'+l.quantity+'</td><td>'+(edit?'<input data-reserve aria-label="Ayrılan miktar" type="number" min="'+p2Planned(l.id)+'" max="'+(l.quantity-l.shipped_qty)+'" step="1" value="'+l.reserved_qty+'">':l.reserved_qty)+'</td><td>'+l.shipped_qty+'</td><td>'+ (l.quantity-l.shipped_qty)+(l.stock_required&&l.reserved_qty<l.quantity-l.shipped_qty?'<br><small style="color:#b54708">Eksik rezervasyon</small>':'')+'</td></tr>';
 }).join('')+'</tbody></table></div>'+(edit?'<button class="btn primary" id="p2Reserve">Rezervasyonu kaydet</button>':'');
 document.getElementById('p2Reserve')?.addEventListener('click',()=>p2Mutation('reserve_operation_stock',{p_order_id:opsDetail.id,p_revision:opsDetail.revision,p_rows:[...document.querySelectorAll('[data-p2-line]')].map(r=>({id:Number(r.dataset.p2Line),product_id:r.querySelector('[data-nonstock]')?.checked?null:r.querySelector('[data-product]').value||null,reserve:r.querySelector('[data-nonstock]')?.checked?0:Number(r.querySelector('[data-reserve]').value),nonstock:r.querySelector('[data-nonstock]')?.checked??!p2Data.lines.find(l=>l.id===Number(r.dataset.p2Line)).stock_required,note:r.querySelector('[data-mapping-note]').value}))}));
 const finance=[...document.querySelectorAll('#opsModalBody .ops-box')].find(x=>x.querySelector('h3')?.textContent==='Muhasebe');finance.querySelector('.p2-documents')?.remove();finance.insertAdjacentHTML('beforeend',p2Files('invoice',null));
 document.getElementById('p2Shipments').innerHTML='<div class="ops-heading"><h3>Sevkiyat ve teslim geçmişi</h3>'+(edit?'<button class="btn primary" id="p2New">+ Sevkiyat planla</button>':'')+'</div><p class="ops-state">Çıkış için fatura kaydı, fatura PDF’i, bu sevkiyatın irsaliye PDF’i ve paketleme tamamlanmalı. Kısmi çıkışta kalan ürünler açık kalır.</p><div id="p2PlanForm"></div>'+p2Data.ships.map(s=>'<article class="ops-box" style="margin-top:14px"><div class="ops-heading"><b>'+esc(s.shipment_number)+'</b><span>'+esc(({planned:'Planlandı',shipped:'Yola çıktı',delivered:'Teslim edildi',cancelled:'İptal edildi'})[s.status])+'</span></div><p>'+esc(opsLabels.method[s.method])+' · Plan: '+esc(s.planned_date)+'<br>'+esc([s.cargo_company,s.tracking_number,s.vehicle_plate,s.delivery_person].filter(Boolean).join(' · '))+'<br>İrsaliye: '+esc(s.dispatch_number||'—')+'</p><div class="ops-products"><table><tbody>'+p2Data.items.filter(i=>i.shipment_id===s.id).map(i=>'<tr><td>'+esc(p2Data.lines.find(l=>l.id===i.order_line_id)?.description||'Ürün')+'</td><td>'+i.quantity+' adet</td><td>'+esc(i.serial_numbers||'—')+'</td></tr>').join('')+'</tbody></table></div><p>Çıkış: '+esc(s.shipped_date||'—')+' · Teslim: '+esc(s.delivered_date||'—')+' · Teslim alan: '+esc(s.received_by||'—')+'</p>'+p2Files('dispatch',s.id)+(p2Editable()&&s.status==='planned'?'<div class="actions"><button class="btn light" data-p2-edit="'+s.id+'">Bilgileri düzenle</button><button class="btn primary" data-p2-dispatch="'+s.id+'">Sevkiyatı çıkar</button><button class="btn light" data-p2-cancel="'+s.id+'">Planı iptal et</button></div>'+opsInput('p2Date'+s.id,'Gerçek çıkış tarihi',p2Today(),'date'):'')+(p2Editable()&&s.status==='shipped'?'<div class="grid">'+opsInput('p2Date'+s.id,'Teslim tarihi',p2Today(),'date')+opsInput('p2Receiver'+s.id,'Teslim alan kişi','')+'</div><button class="btn primary" data-p2-deliver="'+s.id+'">Teslim edildi olarak kaydet</button>':'')+'</article>').join('')+(p2Data.ships.length?'':'<p>Henüz sevkiyat planlanmadı.</p>');
 document.getElementById('p2New')?.addEventListener('click',()=>p2Plan());
 document.querySelectorAll('[data-p2-edit]').forEach(b=>b.onclick=()=>p2Plan(p2Data.ships.find(s=>s.id===Number(b.dataset.p2Edit))));
 for(const action of ['dispatch','deliver','cancel'])document.querySelectorAll('[data-p2-'+action+']').forEach(b=>b.onclick=()=>{
 const sid=Number(b.getAttribute('data-p2-'+action));let data;
 if(action==='cancel'){const reason=prompt('Plan iptal gerekçesi (en az 5 karakter):');if(reason===null)return;data={reason}}
 else if(action==='deliver')data={date:val('p2Date'+sid),received_by:val('p2Receiver'+sid)};
 else{if(!confirm('Bu sevkiyattaki ürünler fiziksel stoktan düşülecek. Çıkışı kaydedelim mi?'))return;data={date:val('p2Date'+sid)}}
 p2Mutation('operation_shipment_action',{p_shipment_id:sid,p_revision:opsDetail.revision,p_action:action,p_data:data});
 });
 document.querySelectorAll('[data-p2-upload]').forEach(el=>el.onchange=()=>p2Upload(el.files[0],el.dataset.p2Upload,Number(el.dataset.shipment)||null));
 document.querySelectorAll('[data-p2-download]').forEach(el=>el.onclick=()=>p2Download(p2Data.docs.find(d=>d.id===el.dataset.p2Download)));
}
function p2Plan(s=null){
 if(!p2Editable()||!p2Data)return;p2Draft={id:s?.id||null,key:crypto.randomUUID()};const d=s||{};
 const box=document.getElementById('p2PlanForm');box.innerHTML='<section class="ops-box" style="background:#edf4ff"><h3>'+(s?'Sevkiyat bilgilerini düzenle':'Yeni sevkiyat planı')+'</h3><div class="grid">'+opsSelect('p2Method','Yöntem',opsLabels.method,d.method||'cargo')+opsInput('p2Planned','Planlanan tarih',d.planned_date||p2Today(),'date')+opsInput('p2Cargo','Kargo firması',d.cargo_company)+opsInput('p2Tracking','Kargo takip numarası',d.tracking_number)+opsInput('p2Plate','Araç plakası',d.vehicle_plate)+opsInput('p2Person','Teslimat sorumlusu / teslim alacak kişi',d.delivery_person)+opsInput('p2DispatchNo','İrsaliye numarası',d.dispatch_number)+opsInput('p2DispatchDate','İrsaliye tarihi',d.dispatch_date,'date')+'</div>'+opsText('p2Note','Sevkiyat notu',d.note)+(s?'<p>Ürün miktarlarını değiştirmek için planı iptal edip yeni plan oluşturun.</p>':'<p>Bu sevkiyata girecek miktarları seçin. Ayrılmamış ürünler gönderilemez.</p><div class="ops-products"><table><thead><tr><th>Ürün</th><th>Planlanabilir</th><th>Bu sevkiyat</th><th>Seri numaraları</th></tr></thead><tbody>'+p2Data.lines.map(l=>'<tr data-p2-plan-line="'+l.id+'"><td>'+esc(l.description)+'</td><td>'+p2Capacity(l)+'</td><td><input data-qty type="number" aria-label="Sevkiyat miktarı" min="0" max="'+p2Capacity(l)+'" step="1" value="0"></td><td><input data-serials aria-label="Seri numaraları" maxlength="2000"></td></tr>').join('')+'</tbody></table></div>')+'<div class="actions"><button class="btn primary" id="p2PlanSave">Planı kaydet</button><button class="btn light" id="p2PlanClose">Vazgeç</button></div></section>';
 document.getElementById('p2PlanClose').onclick=()=>{box.replaceChildren();p2Draft=null};
 document.getElementById('p2PlanSave').onclick=()=>{
 const data={method:val('p2Method'),planned_date:val('p2Planned'),cargo_company:val('p2Cargo'),tracking_number:val('p2Tracking'),vehicle_plate:val('p2Plate'),delivery_person:val('p2Person'),dispatch_number:val('p2DispatchNo'),dispatch_date:val('p2DispatchDate'),note:val('p2Note')};
 if(s)p2Mutation('operation_shipment_action',{p_shipment_id:s.id,p_revision:opsDetail.revision,p_action:'edit',p_data:data});
 else{const rows=[...box.querySelectorAll('[data-p2-plan-line]')].map(r=>({id:Number(r.dataset.p2PlanLine),qty:Number(r.querySelector('[data-qty]').value),serials:r.querySelector('[data-serials]').value})).filter(r=>r.qty!==0);
 if(!rows.length){document.getElementById('opsModalState').textContent='En az bir ürün için gönderilecek miktarı girin.';return}
 p2Mutation('create_operation_shipment',{p_order_id:opsDetail.id,p_revision:opsDetail.revision,p_request_key:p2Draft.key,p_data:data,p_rows:rows})}
 };box.scrollIntoView?.({behavior:'smooth',block:'nearest'});
}
async function p2Refresh(id,key){if(key!==opsKey())return;await openOperationOrder(id);if(!opsOverlay.hidden)await loadOperationOrders();await loadOperationsCounts('opsDashCounts')}
async function p2Mutation(name,args){
 if(opsBusy||!opsDetail||!orderReadAllowed())return;const key=opsKey(),id=opsDetail.id,company=currentCompanyId;opsBusy=true;p2Disable(true);
 try{const {error}=await sb.rpc(name,{p_company_id:company,...args});if(error)throw error;await p2Refresh(id,key)}
 catch(e){if(key===opsKey())document.getElementById('opsModalState').textContent='İşlem tamamlanamadı: '+e.message}
 finally{opsBusy=false;if(key===opsKey())p2Disable(false)}
}
function p2Disable(disabled){document.querySelectorAll('#opsModalBody button,#opsModalBody input[type=file]').forEach(el=>el.disabled=disabled||!!el.closest('fieldset[disabled]'))}
async function p2Upload(file,kind,sid){
 if(!file||opsBusy||!opsDetail||!opsCanEdit(kind==='invoice'?'finance':'warehouse'))return;
 const key=opsKey(),company=currentCompanyId,id=opsDetail.id;let doc=null;opsBusy=true;p2Disable(true);
 try{
 if(!/\.pdf$/i.test(file.name)||file.size<5||file.size>10*1024*1024)throw new Error('En fazla 10 MB boyutunda PDF seçin.');
 const bytes=await file.arrayBuffer();if(String.fromCharCode(...new Uint8Array(bytes).slice(0,5))!=='%PDF-')throw new Error('Dosya geçerli bir PDF değil.');
 const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');
 if(key!==opsKey())return;
 const start=await sb.rpc('begin_operation_document',{p_company_id:company,p_order_id:id,p_kind:kind,p_shipment_id:sid,p_name:file.name,p_size:file.size,p_sha256:sha});if(start.error)throw start.error;doc=start.data;
 if(key!==opsKey())throw new Error('Hesap değişti. Dosya işlemini yeniden başlatın.');
 const upload=await sb.storage.from('operation-documents').upload(doc.path,file,{contentType:'application/pdf',upsert:false});if(upload.error)throw upload.error;
 const finish=await sb.rpc('finish_operation_document',{p_company_id:company,p_id:doc.id,p_abort:false});if(finish.error)throw finish.error;
 await p2Refresh(id,key);
 }catch(e){
 if(doc&&key===opsKey()){try{const cleanup=await sb.storage.from('operation-documents').remove([doc.path]);if(!cleanup.error)await sb.rpc('finish_operation_document',{p_company_id:company,p_id:doc.id,p_abort:true})}catch{}}
 if(key===opsKey())document.getElementById('opsModalState').textContent='PDF eklenemedi: '+e.message+' Yenileyerek belge listesini kontrol edin.';
 }finally{opsBusy=false;if(key===opsKey())p2Disable(false)}
}
