 const today=agendaToday(),since=agendaDateAdd(today,-(Number(val('hdPeriod'))||30)+1)+'T00:00:00+03:00';const jobs=[];
 const count=async(table,filter)=>{let q=sb.from(table).select('id',{head:true,count:'exact'}).eq('company_id',company);q=filter(q);const r=await q;if(r.error)throw r.error;return r.count||0};
