const pgStyle=document.createElement('style');pgStyle.textContent='.guide-overlay{z-index:18000!important;padding:22px!important;background:#071c3db0}.pg-shell{width:min(1140px,96vw);height:min(820px,92dvh);background:#fff;border-radius:16px;box-shadow:0 25px 90px #071c3d55;display:flex;flex-direction:column;overflow:hidden;color:#173352}.pg-header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:24px 28px;border-bottom:1px solid #e4ebf4;background:#f7faff}.pg-header h2{font-size:25px;margin:6px 0;color:#102947;letter-spacing:-.5px}.pg-header p{font-size:12px;color:#637994;margin:8px 0 0}.pg-layout{display:grid;grid-template-columns:270px minmax(0,1fr);min-height:0;flex:1}.pg-sidebar{padding:20px;border-right:1px solid #e5edf6;background:#f8fafd;overflow:auto}.pg-sidebar label{font-size:11px}.pg-sidebar input{font-size:12px}.pg-sidebar nav{display:grid;gap:4px;margin-top:16px}.pg-sidebar nav button{border:0;border-radius:7px;text-align:left;padding:11px 12px;background:transparent;font-size:12px;color:#385572;line-height:1.5;cursor:pointer}.pg-sidebar nav button[aria-current=page]{background:#0878f9;color:white;font-weight:700}.pg-progress{margin-top:22px;padding:15px 5px;border-top:1px solid #dfe7f3;font-size:12px}.pg-progress>div{height:6px;margin:12px 0;background:#dfe9f6;border-radius:5px;overflow:hidden}.pg-progress i{display:block;height:100%;background:#0eaf87}.pg-progress small{font-size:10px;line-height:1.6;color:#7c8fa7}.pg-article{padding:30px 34px;overflow:auto;line-height:1.8;outline-offset:-4px}.pg-article h3{font-size:24px;color:#112b4c;letter-spacing:-.5px;line-height:1.4;margin:4px 0 12px}.pg-article p{font-size:14px;color:#53708e;line-height:1.8}.pg-article ol{padding-left:24px;margin:20px 0}.pg-article li{font-size:14px;color:#284562;margin:0 0 17px;padding-left:6px}.pg-article li::marker{font-weight:800;color:#0878f9}.pg-tip{background:#edf5ff;border:1px solid #dceafa;border-left:3px solid #0878f9;border-radius:8px;padding:14px 17px;font-size:13px;color:#284e77;line-height:1.8}.pg-buttons{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}.pg-buttons .btn{font-size:12px}.pg-bottom{display:flex;justify-content:space-between;gap:12px;align-items:center;border-top:1px solid #e7edf6;padding-top:20px;margin-top:28px}.pg-bottom label{display:flex;align-items:center;gap:9px;font-size:12px;line-height:1.6}.pg-bottom input{width:18px;height:18px;flex-shrink:0}.pg-bottom .btn{font-size:12px}.pg-step{font-size:11px;color:#7287a0}@media(max-width:760px){.guide-overlay{padding:0!important}.pg-shell{width:100%;height:100dvh;border-radius:0}.pg-header{padding:18px}.pg-header h2{font-size:21px}.pg-layout{display:flex;flex-direction:column}.pg-sidebar{border-right:0;border-bottom:1px solid #e5edf6;padding:12px 16px;flex-shrink:0;max-height:220px}.pg-sidebar nav{display:flex;overflow:auto;margin-top:9px;gap:6px}.pg-sidebar nav button{flex-shrink:0;max-width:180px;font-size:11px;padding:8px 10px}.pg-progress{padding:8px 0 0;margin-top:8px}.pg-progress>div{margin:6px 0}.pg-progress small{display:none}.pg-article{padding:22px 20px;flex:1}.pg-article h3{font-size:22px}.pg-article li{font-size:13px}.pg-bottom{flex-wrap:wrap}.pg-bottom label{flex-basis:100%}.pg-sidebar input{font-size:16px}}@media print{.guide-overlay{display:none!important}}';document.head.append(pgStyle);
function pgLoadRead(){try{pgRead=JSON.parse(localStorage.getItem(pgStorageKey())||'{}');if(!pgRead||Array.isArray(pgRead)||typeof pgRead!=='object')pgRead={}}catch{pgRead={}}}
function pgRender(){
 const topics=pgTopics(),query=val('pgSearch').toLocaleLowerCase('tr-TR').trim(),visible=topics.filter(t=>(t.title+' '+t.intro+' '+t.steps.join(' ')+' '+t.tip).toLocaleLowerCase('tr-TR').includes(query));
 if(!visible.some(t=>t.id===pgTopic))pgTopic=visible[0]?.id||'';
 document.getElementById('pgRole').textContent='Rolünüz: '+(teamRoles[currentMembership?.role]||'Şirket sahibi')+' · Rehber mevcut yetkilerinize göre hazırlanır.';
 document.getElementById('pgNav').innerHTML=visible.map(t=>'<button type="button" data-pg-topic="'+t.id+'" '+(t.id===pgTopic?'aria-current="page"':'')+'>'+esc(t.title)+(pgRead[t.id]?' ✓':'')+'</button>').join('')||'<p>Aramanıza uygun konu yok.</p>';
 document.querySelectorAll('[data-pg-topic]').forEach(b=>b.onclick=()=>{pgTopic=b.dataset.pgTopic;pgRender()});
 const done=topics.filter(t=>pgRead[t.id]).length;document.getElementById('pgProgressLabel').textContent=done+' / '+topics.length+' bölüm okundu';document.getElementById('pgProgress').style.width=Math.round(done/topics.length*100)+'%';
 const t=topics.find(t=>t.id===pgTopic),article=document.getElementById('pgArticle');
 if(!t){article.innerHTML='<h3>Sonuç bulunamadı</h3><p>Başka bir kelime deneyin veya arama alanını temizleyin.</p>';return}
 const index=topics.indexOf(t),links=t.links.filter(([,action])=>action==='offers'?offerAllowed():hasAppAction(action));
 article.innerHTML='<small class="pg-step">Bölüm '+(index+1)+' / '+topics.length+'</small><h3>'+esc(t.title)+'</h3><p>'+esc(t.intro)+'</p><ol>'+t.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol><aside class="pg-tip"><b>Bilmeniz gereken:</b> '+esc(t.tip)+'</aside>'+(links.length?'<div class="pg-buttons">'+links.map(([label,action])=>'<button type="button" class="btn primary" data-pg-open="'+action+'">'+esc(label)+' →</button>').join('')+'</div>':'')+'<footer class="pg-bottom"><label><input id="pgReadTopic" type="checkbox" '+(pgRead[t.id]?'checked':'')+'> Bu bölümü okudum</label><div class="actions"><button class="btn light" id="pgPrev" '+(index===0?'disabled':'')+'>Önceki</button><button class="btn primary" id="pgNext">'+(index===topics.length-1?'Rehberi kapat':'Sonraki')+'</button></div></footer>';
 document.getElementById('pgReadTopic').onchange=e=>{pgRead[t.id]=e.target.checked;try{localStorage.setItem(pgStorageKey(),JSON.stringify(pgRead))}catch{}pgRender();document.getElementById('pgReadTopic')?.focus()};
 document.getElementById('pgPrev').onclick=()=>{pgTopic=topics[Math.max(0,index-1)].id;document.getElementById('pgSearch').value='';pgRender()};
 document.getElementById('pgNext').onclick=()=>{if(index===topics.length-1)finishGuide();else{pgTopic=topics[index+1].id;document.getElementById('pgSearch').value='';pgRender()}};
 article.querySelectorAll('[data-pg-open]').forEach(b=>b.onclick=async()=>{const action=b.dataset.pgOpen;if(action==='offers'?!offerAllowed():!hasAppAction(action))return;finishGuide();try{if(action==='offers')await openOffers();else await appNavigate(action)}catch(e){alert('Bölüm açılamadı: '+e.message)}});
 article.scrollTop=0;
}
openGuide=function(){if(!currentUser||!currentCompanyId)return;pgReturnFocus=document.activeElement;pgIdentity=pgKey();pgLoadRead();pgTopic='welcome';document.getElementById('pgSearch').value='';pgRender();pgOverlay.classList.add('open');document.getElementById('pgClose').focus()};
finishGuide=function(){pgOverlay.classList.remove('open');if(pgReturnFocus?.isConnected)pgReturnFocus.focus();pgReturnFocus=null};
guidePrev=function(){document.getElementById('pgPrev')?.click()};
guideNext=function(){document.getElementById('pgNext')?.click()};
document.getElementById('pgSearch').oninput=pgRender;document.getElementById('pgClose').onclick=finishGuide;
pgOverlay.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();finishGuide();return}if(e.key!=='Tab')return;const controls=[...pgOverlay.querySelectorAll('button:not([disabled]),input,select,a[href]')].filter(x=>!x.hidden);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}});
const pgRoleBase=applyRoleNavigation;applyRoleNavigation=function(){pgRoleBase();if(pgIdentity!==pgKey()){finishGuide();pgRead={};document.getElementById('pgArticle').replaceChildren();document.getElementById('pgNav').replaceChildren();pgIdentity=pgKey()}};
const pgClearBase=clearOperations;clearOperations=function(){pgClearBase();if(pgOverlay.classList.contains('open'))finishGuide()};

