function pnAction(b){if(b.dataset.offerNav)return 'offers';const call=b.getAttribute('onclick')||'';return call.match(/Navigate\('([^']+)'\)/)?.[1]||(call.includes('openGuide')?'guide':call.includes('logoutUser')?'logout':null)}
function pnIcon(key){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+pnPaths[key]+'"/></svg>'}
function pnRefresh(){
 const service=currentMembership?.role==='service';
 const labels={home:'Ana Sayfa',calendar:'Takvim',crm:'Görüşmeler',customers:'Müşteriler',offers:service?'Servis Parça Teklifleri':'Fiyat Teklifleri',archive:service?'Servis Proformaları':'Proformalar',new:service?'Yeni Servis Proforması':'Yeni Proforma',catalog:'Ürün Kataloğu',stock:'Stok Kontrolü',service:'Servis Kayıtları',orders:'Sipariş ve Teslimat',organization:'Seyahat Organizasyonları',team:'Ekip ve Roller',settings:'Firma Ayarları',guide:'Başlangıç Rehberi',logout:'Çıkış Yap'};
 const groups=[['ÇALIŞMA ALANI',['home','calendar']],['SATIŞ VE MÜŞTERİLER',service?['crm','customers']:['crm','customers','offers','archive','new']],['ÜRÜN VE STOK',['catalog','stock']],['TEKNİK SERVİS',service?['service','offers','archive','new']:['service']],['OPERASYON',['orders','organization']],['YÖNETİM',['team','settings']]];
 for(const nav of document.querySelectorAll('.ds-nav,.md-menu')){
  const buttons=[...nav.querySelectorAll('button')], map=new Map(buttons.map(b=>[pnAction(b),b]));
  nav.querySelectorAll('.nav-group,.pn-group,.md-sep').forEach(el=>el.remove());
  for(const [title,keys] of groups){const present=keys.map(k=>map.get(k)).filter(Boolean);if(!present.length)continue;const head=document.createElement('div');head.className='pn-group';head.textContent=title;head.hidden=!present.some(b=>!b.hidden&&b.style.display!=='none');nav.append(head,...present)}
  for(const k of ['guide','logout'])if(map.get(k))nav.append(map.get(k));
 }
 for(const b of document.querySelectorAll('.desktop-side button,.md-menu button')){const key=pnAction(b);if(!labels[key])continue;b.dataset.pnAction=key;b.innerHTML='<span class="'+(b.closest('.md-menu')?'mi':'ds-icon')+'">'+pnIcon(key)+'</span><span class="pn-label">'+labels[key]+'</span>';b.type='button'}
 const profile=document.querySelector('.ds-profile>span');if(profile)profile.textContent=({owner:'Şirket Sahibi',accounting:'Muhasebe',logistics:'Lojistik',...teamRoles})[currentMembership?.role]||'Firma çalışma alanı';
}
const pnRoleBase=applyRoleNavigation;applyRoleNavigation=function(){const result=pnRoleBase.apply(this,arguments);pnRefresh();return result};
