const orgOverlay=document.createElement('section');orgOverlay.id='organizationOverlay';orgOverlay.className='organization-overlay';orgOverlay.hidden=true;orgOverlay.innerHTML='<div class="organization-shell"><header class="org-head"><div><small class="workspace-kicker">OPERASYON · PLAN VE ORGANİZASYON</small><h1>Seyahat Organizasyonları</h1><p>Şehir içi araç, şehir dışı bilet, otel ve hazırlık talepleri.</p></div><button class="btn light" type="button" onclick="appNavigate(\'home\')">Kapat</button></header><div class="org-toolbar"><input id="orgSearch" placeholder="Başlık veya şehir ara"><select id="orgFilter"><option value="active">Aktif talepler</option><option value="all">Tümü</option>'+Object.entries(orgStates).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select><button class="btn light" type="button" onclick="orgLoad()">Yenile</button></div><p id="orgMessage" role="status"></p><div class="org-workspace"><div id="orgList"></div><section id="orgDetail"><div class="hd-empty">İncelemek için bir plan seçin.</div></section></div></div>';document.body.append(orgOverlay);
const orgNavigateBase=appNavigate;appNavigate=function(action){if(action!=='organization')return orgNavigateBase(action);if(!hasAppAction(action))return;closeAllProeraViews();orgOverlay.hidden=false;for(const b of document.querySelectorAll('.ds-nav button,.md-menu button')){const active=pnAction(b)==='organization';b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}return orgLoad()};
