async function orgAction(x,action,extra){if(orgSaving)return;let data=extra||{};if(['reject','cancel'].includes(action)){const reason=prompt('Açıklama yazın (en az 5 karakter):');if(!reason)return;data={reason}}if(['save','ready'].includes(action)){document.querySelectorAll('#orgDetail [data-org-field]').forEach(el=>data[el.dataset.orgField]=el.value.trim())}orgSaving=true;const company=currentCompanyId;document.getElementById('orgMessage').textContent='Kaydediliyor…';try{const {error}=await sb.rpc('organization_action',{p_company_id:company,p_id:x.id,p_revision:x.revision,p_action:action,p_data:data});if(error)throw error;if(company===currentCompanyId){await orgLoad();document.getElementById('orgMessage').textContent='İşlem kaydedildi. Çalışan kendi planında güncel bilgileri görebilir.'}}catch(e){alert('Organizasyon kaydedilemedi: '+e.message);if(company===currentCompanyId)await orgLoad()}finally{orgSaving=false}}
async function orgUpload(x,kind,file){if(!file||orgSaving)return;if(file.size>10485760||!file.name.toLowerCase().endsWith('.pdf')){alert('En fazla 10 MB PDF seçin.');return}const bytes=new Uint8Array(await file.slice(0,5).arrayBuffer());if(String.fromCharCode(...bytes)!=='%PDF-'){alert('Geçerli PDF seçin.');return}if(x.company_id!==currentCompanyId)return;const path=currentCompanyId+'/'+x.id+'/'+crypto.randomUUID()+'.pdf';const {error}=await sb.storage.from('organization-documents').upload(path,file,{contentType:'application/pdf',upsert:false});if(error){alert('Belge yüklenemedi: '+error.message);return}if(x.company_id!==currentCompanyId)return;await orgAction(x,'document',{kind,path})}
async function orgDownload(path){const company=currentCompanyId;const {data,error}=await sb.storage.from('organization-documents').download(path);if(error){alert('Belge indirilemedi: '+error.message);return}if(company!==currentCompanyId)return;const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='organizasyon-belgesi.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
