const orgForm=document.createElement('section');orgForm.className='trip-panel';orgForm.id='organizationPlanForm';orgForm.innerHTML='<h3>Plan ve organizasyon ihtiyacı</h3><p class="muted">İhtiyaç yoksa yalnızca takvim kaydı oluşur. Bilet / otel yönetim onayına, diğer ihtiyaçlar operasyona gider.</p><div class="org-detail-grid"><label>Plan türü<select id="orgScope"><option value="local">Şehir içi</option><option value="outstation">Şehir dışı</option></select></label><label>Ulaşım<select id="orgTransport">'+Object.entries(orgTransport).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label><label>Gidiş / hareket<input id="orgDeparture" type="datetime-local"></label><label>Dönüş / bitiş<input id="orgReturn" type="datetime-local"></label><label>İlçe<input id="orgDistrict" maxlength="200"></label><label>Açık adres / buluşma<input id="orgAddress" maxlength="1000"></label><label>Diğer katılımcılar<select id="orgParticipants" multiple size="3"></select><small>Sorumlu kişi ve planı oluşturan zaten erişebilir. Ctrl ile birden fazla kişi seçin.</small></label><div class="org-needs"><label><input id="orgHotel" type="checkbox"> Otel gerekli</label><label><input id="orgTransfer" type="checkbox"> Transfer gerekli</label><label><input id="orgEquipment" type="checkbox"> Ekipman taşıma gerekli</label></div><label>Otel giriş<input id="orgCheckin" type="date"></label><label>Otel çıkış<input id="orgCheckout" type="date"><small id="orgNights"></small></label></div><div id="calendarOrgDetail"></div>';document.getElementById('tripPreparation').before(orgForm);
document.getElementById('calTravel').closest('label').hidden=true;document.querySelector('#tripPreparation>p').textContent='Ziyaret öncesi kişisel müşteri teyidi ve ekipman kontrolü. Bilet, otel ve araç bilgilerini operasyon hazırlayacak.';
function orgSetPlan(p={}){document.getElementById('orgScope').value=p.scope||'local';document.getElementById('orgTransport').value=p.transport||'own';document.getElementById('orgDeparture').value=p.departure||val('calDate')+'T'+(val('calStart')||'09:00');document.getElementById('orgReturn').value=p.return_at||val('calDate')+'T'+(val('calEnd')||'18:00');for(const [id,key] of [['orgDistrict','district'],['orgAddress','address'],['orgCheckin','checkin'],['orgCheckout','checkout']])document.getElementById(id).value=p[key]||'';for(const [id,key] of [['orgHotel','hotel'],['orgTransfer','transfer'],['orgEquipment','equipment']])document.getElementById(id).checked=!!p[key];orgParticipants=p.participants||[];orgFillParticipants();orgUpdateNeeds();document.getElementById('calendarOrgDetail').replaceChildren()}
function orgFillParticipants(){const el=document.getElementById('orgParticipants');if(!el)return;const selected=[...el.selectedOptions].map(x=>x.value);el.replaceChildren(...[...document.getElementById('calAssignee').options].filter(o=>o.value).map(o=>{const x=new Option(o.textContent,o.value);x.selected=(selected.length?selected:orgParticipants).includes(o.value);return x}))}
new MutationObserver(orgFillParticipants).observe(document.getElementById('calAssignee'),{childList:true});
function orgUpdateNeeds(){const hotel=document.getElementById('orgHotel').checked;for(const id of ['orgCheckin','orgCheckout'])document.getElementById(id).closest('label').hidden=!hotel;document.getElementById('orgNights').textContent=orgNights({hotel,checkin:val('orgCheckin'),checkout:val('orgCheckout')})+' gece';document.getElementById('calTravel').checked=val('orgScope')==='outstation';renderTripTasks()}
for(const id of ['orgScope','orgHotel','orgCheckin','orgCheckout'])document.getElementById(id).addEventListener('change',orgUpdateNeeds);
