const orgNewBase=newCalendarEvent;newCalendarEvent=function(date){orgNewBase(date);orgSetPlan()};
let orgCalendarVersion=0;const orgEditBase=editCalendarEvent;editCalendarEvent=function(id){orgEditBase(id);const e=tripCurrentEvent();orgSetPlan(e?.organization_plan||{scope:e?.travel_required?'outstation':'local'});orgCalendarRead(id)};
async function orgCalendarRead(id){const company=currentCompanyId,key=opsKey(),v=++orgCalendarVersion;const {data,error}=await sb.from('event_organizations').select('*').eq('company_id',company).eq('event_id',id).maybeSingle();if(v!==orgCalendarVersion||company!==currentCompanyId||key!==opsKey()||val('calId')!==String(id))return;if(error){document.getElementById('calendarOrgDetail').textContent='Organizasyon bilgileri yüklenemedi: '+error.message;return}if(data)orgRenderDetail(data,document.getElementById('calendarOrgDetail'),true)}
