const orgTripRenderBase=renderTripTasks;renderTripTasks=function(){orgTripRenderBase();for(const el of document.querySelectorAll('#tripTaskList [data-trip-task]'))if(['flight','hotel','transfer'].includes(el.dataset.tripTask))el.closest('label').hidden=true};
