async function orgLoadHome(){const company=currentCompanyId,key=opsKey(),v=++orgHomeToken;orgHome.hidden=true;orgHome.replaceChildren();if(!hasAppAction('organization')||!currentUser||!company)return;const {data,error}=await sb.from('event_organizations').select('id,title,city,status,departure,return_at,plan').eq('company_id',company).not('status','in','(completed,cancelled)').gte('return_at',agendaToday()).order('departure').limit(10);if(v!==orgHomeToken||company!==currentCompanyId||key!==opsKey()||!hasAppAction('organization'))return;if(error){orgHome.hidden=false;orgHome.textContent='Organizasyon durumları yüklenemedi: '+error.message;return}if(!data?.length)return;orgHome.hidden=false;orgHome.innerHTML='<div class="hd-panel-head"><h3>Plan ve organizasyon takibi</h3><button type="button" class="btn light" id="orgHomeOpen">Tümünü aç</button></div><p class="hd-note">Yaklaşan en fazla 10 organizasyon · '+(orgOperator()?'Hazırlanacak bilet, otel ve araç işleri.':'Planlarınızın onay ve hazırlık durumları.')+'</p>'+data.map(x=>'<button type="button" class="org-home-row" data-org-home="'+esc(x.id)+'"><span><b>'+esc(x.title)+'</b><small>'+esc(x.city)+' · '+esc(orgDate(x.departure))+'</small></span><span class="org-state state-'+esc(x.status)+'">'+orgStates[x.status]+'</span></button>').join('');document.getElementById('orgHomeOpen').onclick=()=>appNavigate('organization');orgHome.querySelectorAll('[data-org-home]').forEach(b=>b.onclick=async()=>{const id=b.dataset.orgHome;await appNavigate('organization');orgSelected=orgRows.find(x=>x.id===id)||null;if(orgSelected){document.getElementById('orgFilter').value='all';orgRenderList();orgRenderDetail(orgSelected)}})}
