// Private product images, normalized in-browser without changing the source file.
let piBlob=null,piPath=null,piDirty=false,piBusy=false,piPreviewURL='',piEditToken=0,piScope='',piCache=new Map(),piJobs=0,piQueue=[];
function piCanWrite(){return ['owner','admin','manager'].includes(currentMembership?.role)}
const piBox=document.createElement('section');piBox.className='product-image-editor full';piBox.innerHTML='<div class="pi-preview" id="piPreview"></div><div><h3>Ürün görseli</h3><p>JPG, PNG veya WEBP · En fazla 10 MB. Görsel kesilmeden ve esnetilmeden, beyaz zeminli 800 × 800 kareye yerleştirilir.</p><label class="btn light pi-upload">Görsel seç / değiştir<input id="piFile" type="file" accept="image/jpeg,image/png,image/webp"></label> <button type="button" class="btn light" id="piRemove">Görseli kaldır</button><p id="piMessage" role="status">Görsel isteğe bağlıdır.</p></div>';document.querySelector('.catalog-grid').append(piBox);
function piPlaceholder(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="m12 3 8 4-8 4-8-4zM4 7v10l8 4 8-4V7M12 11v10"/></svg>'}
function piShowPreview(url){const box=document.getElementById('piPreview');box.replaceChildren();if(url){const img=document.createElement('img');img.src=url;img.alt='Ürün görseli önizlemesi';box.append(img)}else box.innerHTML=piPlaceholder();document.getElementById('piRemove').disabled=!piPath&&!piBlob;}
function piReset(){++piEditToken;piBlob=null;piPath=null;piDirty=false;piBusy=false;if(piPreviewURL){URL.revokeObjectURL(piPreviewURL);piPreviewURL=''}document.getElementById('piFile').value='';document.getElementById('piMessage').textContent='Görsel isteğe bağlıdır.';piShowPreview('')}
function piFit(w,h){const scale=720/Math.max(w,h);return {w:w*scale,h:h*scale,x:(800-w*scale)/2,y:(800-h*scale)/2}}
async function piNormalize(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760)throw Error('En fazla 10 MB JPG, PNG veya WEBP seçin.');let bitmap;if(typeof createImageBitmap==='function')bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});else{const u=URL.createObjectURL(file);try{bitmap=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Görsel okunamadı.'));im.src=u})}finally{URL.revokeObjectURL(u)}}try{const w=bitmap.width,h=bitmap.height;if(!w||!h||w*h>40000000)throw Error('Görsel çok büyük veya bozuk; daha küçük bir fotoğraf seçin.');const canvas=document.createElement('canvas');canvas.width=800;canvas.height=800;const c=canvas.getContext('2d');if(!c)throw Error('Tarayıcı görsel hazırlamayı desteklemiyor.');c.fillStyle='#ffffff';c.fillRect(0,0,800,800);c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';const f=piFit(w,h);c.drawImage(bitmap,f.x,f.y,f.w,f.h);const b=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.82));if(!b||b.size>2097152)throw Error('Görsel sıkıştırılamadı; daha küçük bir dosya seçin.');return b}finally{bitmap.close?.()}}
document.getElementById('piFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!piCanWrite()){alert('Ürün görselini değiştirme yetkiniz yok.');return}const token=++piEditToken,key=opsKey();piBusy=true;document.getElementById('piMessage').textContent='Görsel hazırlanıyor…';try{const b=await piNormalize(file);if(token!==piEditToken||key!==opsKey())return;piBlob=b;piDirty=true;if(piPreviewURL)URL.revokeObjectURL(piPreviewURL);piPreviewURL=URL.createObjectURL(b);piShowPreview(piPreviewURL);document.getElementById('piMessage').textContent='800 × 800 · '+Math.ceil(b.size/1024)+' KB · Ürünü kaydettiğinizde yüklenecek.'}catch(err){if(token===piEditToken)document.getElementById('piMessage').textContent=err.message}finally{if(token===piEditToken)piBusy=false}};
document.getElementById('piRemove').onclick=()=>{if(!piCanWrite())return;++piEditToken;piBlob=null;piPath=null;piDirty=true;piBusy=false;if(piPreviewURL){URL.revokeObjectURL(piPreviewURL);piPreviewURL=''}piShowPreview('');document.getElementById('piMessage').textContent='Görsel, ürünü kaydettiğinizde kaldırılacak.'};
async function piPrepareSave(){if(piBusy)throw Error('Görsel hazırlanıyor; bitmesini bekleyin.');if(!piDirty)return piPath;if(!piCanWrite())throw Error('Görsel yükleme yetkiniz yok.');if(!piBlob)return null;const key=opsKey(),path=currentCompanyId+'/'+crypto.randomUUID()+(piBlob.type==='image/webp'?'.webp':'.png');const {error}=await sb.storage.from('product-images').upload(path,piBlob,{contentType:piBlob.type,upsert:false});if(error)throw Error('Görsel yüklenemedi: '+error.message);if(key!==opsKey())throw Error('Çalışma alanı değişti; yeniden açın.');return path}
const piClearBase=clearCatalogForm;clearCatalogForm=function(){piClearBase();piReset()};
const piEditBase=editCatalogProduct;editCatalogProduct=function(id){piEditBase(id);piReset();const p=(window._catalog||[]).find(x=>String(x.id)===String(id));piPath=p?.image_path||null;if(piPath){const token=piEditToken;document.getElementById('piMessage').textContent='Kayıtlı görsel yükleniyor…';piGetURL(piPath).then(url=>{if(token===piEditToken){piShowPreview(url);document.getElementById('piMessage').textContent=url?'Kayıtlı görsel. Yeni görsel seçebilir veya kaldırabilirsiniz.':'Görsel yüklenemedi; ürünü kaydetmek mevcut görseli değiştirmez.'}})}};
function piClearCache(){piScope=opsKey();for(const url of piCache.values())if(typeof url==='string')URL.revokeObjectURL(url);piCache.clear();for(const job of piQueue)job.resolve('');piQueue=[];for(const img of document.querySelectorAll('img[data-pi-path]'))img.removeAttribute('src')}
function piGetURL(path){if(piScope!==opsKey())piClearCache();if(piCache.has(path))return Promise.resolve(piCache.get(path));const key=opsKey();const promise=new Promise(resolve=>{piQueue.push({path,key,resolve});piRunQueue()});piCache.set(path,promise);return promise}
function piRunQueue(){while(piJobs<4&&piQueue.length){const job=piQueue.shift();piJobs++;(async()=>{try{const {data,error}=await sb.storage.from('product-images').download(job.path);if(error||!data)throw error||Error('Görsel bulunamadı');if(job.key!==opsKey()){job.resolve('');return}const u=URL.createObjectURL(data);piCache.set(job.path,u);job.resolve(u)}catch(e){if(job.key===opsKey())piCache.delete(job.path);job.resolve('')}finally{piJobs--;piRunQueue()}})()}}
function piLoadImg(img){const key=opsKey();piGetURL(img.dataset.piPath).then(url=>{if(url&&key===opsKey()&&img.isConnected){img.src=url;img.hidden=false;img.parentElement.querySelector('svg')?.remove()}})}
const piObserver=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{for(const x of entries)if(x.isIntersecting){piObserver.unobserve(x.target);piLoadImg(x.target.querySelector('img')||x.target)}},{rootMargin:'150px'}):null;
function piThumb(p,large=false){const box=document.createElement('div');box.className='pi-thumb'+(large?' pi-large':'');box.innerHTML=piPlaceholder();if(p?.image_path){const img=document.createElement('img');img.hidden=true;img.alt=p.name||'Ürün';img.dataset.piPath=p.image_path;img.decoding='async';img.onerror=()=>{img.hidden=true;if(!box.querySelector('svg'))box.insertAdjacentHTML('afterbegin',piPlaceholder())};box.append(img);if(piObserver)piObserver.observe(box);else queueMicrotask(()=>piLoadImg(img))}return box}
function piDecorate(){if(piScope!==opsKey())piClearCache();const rows=window._catalog||[];document.querySelectorAll('#catalogList .catalog-row').forEach(row=>{row.querySelector('.pi-thumb')?.remove();const id=row.dataset.productId||row.querySelector('.catalog-pick')?.value||row.querySelector('button[onclick]')?.getAttribute('onclick')?.match(/\((\d+)\)/)?.[1];const p=rows.find(x=>String(x.id)===String(id));if(p){const text=row.querySelector('div');if(text){text.classList.add('pi-product-title');text.prepend(piThumb(p))}row.addEventListener('click',()=>queueMicrotask(()=>piSideImage(p)))}});const selected=document.querySelector('#catalogList .catalog-row.selected');const id=selected?.dataset.productId;if(id)piSideImage(rows.find(x=>String(x.id)===id))}
function piSideImage(p){const side=document.querySelector('.catalog-side');if(!side||!p)return;side.querySelector('.pi-thumb')?.remove();side.prepend(piThumb(p,true))}
const piLoadBase=loadCatalog;loadCatalog=async function(){const key=opsKey();await piLoadBase();if(key===opsKey())piDecorate()};
const piRoleBase=applyRoleNavigation;applyRoleNavigation=function(){piRoleBase();piBox.hidden=!piCanWrite();if(piScope&&piScope!==opsKey()){piReset();piClearCache()}};
